insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('e4000000-0000-0000-0000-000000000001', 'ukmla', '50451506-53da-4af3-bffa-e5f23922ca75',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('e4000000-0000-0000-0000-000000000001', 'A', 'Stop ramipril and ibuprofen and give intravenous crystalloid fluid resuscitation', true, 'Correct. This is pre-renal AKI from volume depletion (vomiting, poor intake) compounded by an ACE inhibitor and an NSAID, both of which impair renal autoregulation when the patient is volume-depleted. The priority is to stop both nephrotoxic/renally-acting drugs and restore renal perfusion with intravenous fluids.', 1),
('e4000000-0000-0000-0000-000000000001', 'B', 'Continue ramipril and ibuprofen but add intravenous furosemide to increase urine output', false, 'Ruled out because furosemide would worsen volume depletion in a patient who is already dehydrated and hypotensive, and continuing the ACE inhibitor and NSAID would perpetuate the renal hypoperfusion causing the AKI.', 2),
('e4000000-0000-0000-0000-000000000001', 'C', 'Arrange urgent renal ultrasound before making any changes to his medications', false, 'Ruled out because the clinical picture (dehydration, drug history, bland urinalysis) is consistent with pre-renal AKI; imaging is not the immediate priority and should not delay stopping nephrotoxic drugs and giving fluids.', 3),
('e4000000-0000-0000-0000-000000000001', 'D', 'Start empirical haemodialysis given the significant rise in creatinine', false, 'Ruled out because there is no indication for dialysis here (no severe hyperkalaemia, refractory acidosis, or fluid overload); the AKI is likely to improve with fluid resuscitation and stopping the causative drugs.', 4),
('e4000000-0000-0000-0000-000000000001', 'E', 'Increase the ramipril dose to improve renal protection', false, 'Ruled out because increasing an ACE inhibitor in the context of volume depletion and AKI would further reduce glomerular perfusion pressure and worsen renal function.', 5),
('e4000000-0000-0000-0000-000000000002', 'A', 'Give intravenous furosemide to increase urine output', false, 'Ruled out because the problem is mechanical outflow obstruction; diuretics will not overcome this and administering them without first relieving the obstruction is inappropriate and potentially harmful.', 1),
('e4000000-0000-0000-0000-000000000002', 'B', 'Start renal replacement therapy immediately without attempting catheterisation', false, 'Ruled out because the obstruction is easily reversible with catheterisation, which should be attempted first; dialysis would only be considered if the AKI and hyperkalaemia failed to resolve or were immediately life-threatening despite decompression.', 2),
('e4000000-0000-0000-0000-000000000002', 'C', 'Arrange an outpatient urology review in two weeks', false, 'Ruled out because this is an acute obstructive AKI with significant biochemical derangement requiring immediate decompression, not delayed outpatient assessment.', 3),
('e4000000-0000-0000-0000-000000000002', 'D', 'Perform a digital rectal examination and reassure if the prostate feels benign', false, 'Ruled out because this does not address the acute urinary retention and obstructive AKI, which requires immediate bladder decompression regardless of prostate examination findings.', 4),
('e4000000-0000-0000-0000-000000000002', 'E', 'Insert a urethral catheter urgently to relieve the obstruction', true, 'Correct. This is post-renal (obstructive) AKI due to bladder outlet obstruction from BPH, causing bilateral hydronephrosis and a rising creatinine with hyperkalaemia. Urgent catheterisation to relieve the obstruction is the key initial step and will usually lead to rapid improvement in renal function.', 5),
('e4000000-0000-0000-0000-000000000003', 'A', 'Give a nebulised salbutamol dose and reassess in one hour before any other treatment', false, 'Ruled out because nebulised salbutamol shifts potassium intracellularly but has a slower onset and does not provide the immediate cardiac membrane stabilisation needed when ECG changes are already present; calcium gluconate should be given first.', 1),
('e4000000-0000-0000-0000-000000000003', 'B', 'Start an insulin-dextrose infusion alone and withhold calcium gluconate', false, 'Ruled out because insulin-dextrose lowers serum potassium over 15-60 minutes by shifting it intracellularly but does not protect the myocardium acutely; calcium gluconate must be given first when ECG changes are present.', 2),
('e4000000-0000-0000-0000-000000000003', 'C', 'Give a potassium-binding resin (e.g. calcium resonium) as the first-line emergency treatment', false, 'Ruled out because potassium-binding resins act slowly over many hours to days by removing potassium via the gut and have no role in the acute emergency stabilisation of life-threatening hyperkalaemia.', 3),
('e4000000-0000-0000-0000-000000000003', 'D', 'Give intravenous calcium gluconate immediately to stabilise the cardiac membrane', true, 'Correct. ECG changes of severe hyperkalaemia (tall tented T waves, widening QRS, loss of P waves) indicate a risk of imminent life-threatening arrhythmia. IV calcium gluconate (or calcium chloride) acts within minutes to stabilise the myocardial membrane and should be given first, before other potassium-lowering measures.', 4),
('e4000000-0000-0000-0000-000000000003', 'E', 'Arrange urgent haemodialysis before giving any other treatment', false, 'Ruled out because although dialysis may ultimately be needed if potassium fails to respond to medical therapy, immediate bedside treatment (calcium gluconate, then insulin-dextrose) must be started first while dialysis is arranged, not delayed until dialysis access is obtained.', 5),
('e4000000-0000-0000-0000-000000000004', 'A', 'Continue metformin as normal since it has no interaction with contrast media', false, 'Ruled out because metformin is renally excreted and should be paused periprocedurally in patients with reduced renal function receiving iodinated contrast, due to the risk of lactic acidosis if AKI occurs.', 1),
('e4000000-0000-0000-0000-000000000004', 'B', 'Ensure adequate intravenous hydration before and after the scan and temporarily withhold metformin around the time of contrast administration', true, 'Correct. Patients with reduced renal function are at increased risk of contrast-induced nephropathy; intravenous hydration reduces this risk. Metformin should be temporarily withheld around iodinated contrast exposure in patients with reduced renal function because of the small risk of lactic acidosis if contrast-induced AKI develops.', 2),
('e4000000-0000-0000-0000-000000000004', 'C', 'Stop ramipril and atorvastatin permanently before the scan', false, 'Ruled out because atorvastatin has no relevant interaction requiring cessation, and while ACE inhibitors may sometimes be paused periprocedurally in high-risk patients, permanent discontinuation is not indicated; temporary metformin cessation and hydration are the key steps.', 3),
('e4000000-0000-0000-0000-000000000004', 'D', 'Restrict oral fluids for 12 hours before the scan to reduce renal workload', false, 'Ruled out because fluid restriction increases the risk of contrast-induced nephropathy; adequate hydration, not restriction, is protective.', 4),
('e4000000-0000-0000-0000-000000000004', 'E', 'Cancel the scan permanently, as CT contrast is absolutely contraindicated in CKD', false, 'Ruled out because CKD is not an absolute contraindication to contrast; with appropriate precautions (hydration, temporary metformin cessation, using the lowest adequate contrast volume) the scan can usually still be performed if clinically indicated.', 5),
('e4000000-0000-0000-0000-000000000005', 'A', 'Give a further intravenous fluid bolus to improve renal perfusion', false, 'Ruled out because the patient already has pulmonary oedema and hypoxia from fluid overload; further fluid would worsen respiratory failure rather than help, and the underlying problem now requires renal replacement therapy.', 1),
('e4000000-0000-0000-0000-000000000005', 'B', 'Repeat the insulin-dextrose infusion and reassess potassium in six hours', false, 'Ruled out because the hyperkalaemia has already failed to respond to insulin-dextrose, calcium gluconate and salbutamol; combined with refractory acidosis and fluid overload, this is an indication for urgent dialysis, not repeating the same medical measures.', 2),
('e4000000-0000-0000-0000-000000000005', 'C', 'Urgent referral for renal replacement therapy', true, 'Correct. This patient has multiple absolute indications for urgent renal replacement therapy: refractory hyperkalaemia unresponsive to medical treatment, severe fluid overload with pulmonary oedema and hypoxia, and severe refractory metabolic acidosis. Delaying dialysis further risks cardiac arrest or respiratory failure.', 3),
('e4000000-0000-0000-0000-000000000005', 'D', 'Start oral sodium bicarbonate to correct the acidosis before considering dialysis', false, 'Ruled out because severe refractory metabolic acidosis in this context is itself an indication for renal replacement therapy; oral bicarbonate would not adequately or rapidly correct this degree of acidosis and delays definitive treatment.', 4),
('e4000000-0000-0000-0000-000000000005', 'E', 'Discharge home with outpatient nephrology follow-up once oxygen saturations improve slightly', false, 'Ruled out because this patient is critically unwell with multiple organ systems affected by severe AKI; discharge would be unsafe and renal replacement therapy is urgently required.', 5),
('e4000000-0000-0000-0000-000000000006', 'A', 'Urethral catheterisation to relieve the retention, followed by measurement of residual volume', true, 'Correct. Acute urinary retention is a urological emergency requiring prompt bladder decompression with a urethral catheter. The residual volume should be documented, and the patient started on an alpha-blocker to aid a trial without catheter, with further urology follow-up for his underlying BPH.', 1),
('e4000000-0000-0000-0000-000000000006', 'B', 'Prescribe an alpha-blocker and review in the outpatient clinic in two weeks', false, 'Ruled out because acute urinary retention requires immediate bladder decompression; an alpha-blocker alone does not relieve the acute obstruction and outpatient review is too delayed for this emergency presentation.', 2),
('e4000000-0000-0000-0000-000000000006', 'C', 'Arrange an urgent transrectal ultrasound-guided prostate biopsy', false, 'Ruled out because there is no suggestion of malignancy here (smooth, non-tender prostate) and biopsy is not the acute management of urinary retention; catheterisation takes priority.', 3),
('e4000000-0000-0000-0000-000000000006', 'D', 'Perform suprapubic aspiration of the bladder using a needle and syringe', false, 'Ruled out because urethral catheterisation is the standard first-line method of bladder decompression in acute retention; needle aspiration is not appropriate management and only provides temporary, incomplete relief.', 4),
('e4000000-0000-0000-0000-000000000006', 'E', 'Restrict oral fluids and observe for spontaneous resolution', false, 'Ruled out because acute urinary retention will not resolve spontaneously and risks progressive renal impairment and bladder damage if not promptly decompressed.', 5),
('e4000000-0000-0000-0000-000000000007', 'A', 'Arrange a Doppler ultrasound and await the result before deciding on surgery', false, 'Ruled out because waiting for imaging delays definitive treatment and risks testicular infarction; when clinical suspicion of torsion is high, urgent surgical exploration should proceed without waiting for ultrasound.', 1),
('e4000000-0000-0000-0000-000000000007', 'B', 'Start oral antibiotics for presumed epididymo-orchitis and review in 24 hours', false, 'Ruled out because the clinical features (sudden severe onset, high-riding horizontal testis, absent cremasteric reflex) are typical of torsion rather than epididymo-orchitis, which usually has a more gradual onset with urinary symptoms; delaying treatment risks losing the testis.', 2),
('e4000000-0000-0000-0000-000000000007', 'C', 'Apply manual detorsion in the emergency department and discharge if pain resolves', false, 'Ruled out because although manual detorsion may be attempted by experienced clinicians as a temporising measure, it is not reliable or definitive, and the patient still requires urgent surgical exploration and fixation; discharge without surgery is inappropriate.', 3),
('e4000000-0000-0000-0000-000000000007', 'D', 'Give analgesia and reassess in the morning as an outpatient', false, 'Ruled out because testicular torsion is a surgical emergency with a narrow window for testicular salvage; delaying assessment risks irreversible testicular loss.', 4),
('e4000000-0000-0000-0000-000000000007', 'E', 'Urgent surgical exploration without waiting for imaging', true, 'Correct. This presentation (sudden severe pain, high-riding horizontal testis, absent cremasteric reflex) is classic for testicular torsion, which is a time-critical surgical emergency. Testicular salvage rates fall sharply after 6 hours of ischaemia, so immediate surgical exploration should not be delayed for imaging if the clinical suspicion is high.', 5),
('e4000000-0000-0000-0000-000000000008', 'A', 'Urgent surgical exploration for suspected testicular torsion', false, $x$Ruled out because the gradual onset, preserved cremasteric reflex, and positive Prehn's sign (pain relief on elevation) make torsion unlikely; surgical exploration is reserved for cases where torsion cannot be confidently excluded clinically, which is not the case here.$x$, 1),
('e4000000-0000-0000-0000-000000000008', 'B', 'Reassurance only, as this will resolve spontaneously without treatment', false, 'Ruled out because untreated bacterial epididymo-orchitis, particularly from an STI, can lead to complications such as abscess formation or infertility, and appropriate antibiotics with contact tracing are needed.', 2),
('e4000000-0000-0000-0000-000000000008', 'C', 'Empirical antibiotics covering Chlamydia trachomatis and Neisseria gonorrhoeae, with sexual health screening', true, $x$Correct. The gradual onset, preserved cremasteric reflex, pain relief with scrotal elevation (Prehn's sign) and urethral discharge in a young sexually active man point to epididymo-orchitis, most likely due to a sexually transmitted infection. Empirical antibiotic cover (e.g. doxycycline, with ceftriaxone if gonorrhoea is suspected) alongside sexual health screening and contact tracing is appropriate.$x$, 3),
('e4000000-0000-0000-0000-000000000008', 'D', 'Advise scrotal support and review in six weeks with no other intervention', false, 'Ruled out because although scrotal support and analgesia are helpful adjuncts, antibiotics targeting the likely causative organisms and sexual health screening should not be delayed six weeks.', 4),
('e4000000-0000-0000-0000-000000000008', 'E', 'Arrange outpatient PSA testing to exclude prostate cancer as the cause', false, 'Ruled out because there is nothing in this presentation to suggest prostate malignancy; the clinical picture is consistent with an infective epididymo-orchitis, and PSA testing is not relevant to acute management.', 5),
('e4000000-0000-0000-0000-000000000009', 'A', 'Testicular tumour', false, 'Ruled out because testicular tumours typically present as a painless, firm or hard swelling arising from the testis itself, which does not transilluminate, unlike the soft, fluid-filled, transilluminating swelling described here.', 1),
('e4000000-0000-0000-0000-000000000009', 'B', 'Varicocele', false, $x$Ruled out because a varicocele classically feels like a 'bag of worms' due to dilated veins in the pampiniform plexus, is usually more prominent on standing, and does not transilluminate as a fluid-filled swelling does.$x$, 2),
('e4000000-0000-0000-0000-000000000009', 'C', 'Inguinal hernia', false, 'Ruled out because an inguinal hernia typically extends from the inguinal canal, may be reducible, often has a cough impulse, and does not usually transilluminate in the way a hydrocele does.', 3),
('e4000000-0000-0000-0000-000000000009', 'D', 'Hydrocele', true, 'Correct. A hydrocele is a painless, fluctuant scrotal swelling that transilluminates brightly, reflecting the collection of clear fluid within the tunica vaginalis surrounding the testis; the testis itself is usually palpable separately and feels normal.', 4),
('e4000000-0000-0000-0000-000000000009', 'E', 'Epididymal cyst', false, 'Ruled out because an epididymal cyst is typically a discrete, smooth swelling felt separately at the head of the epididymis (posterior to the testis) rather than a swelling that surrounds the testis anteriorly as described.', 5),
('e4000000-0000-0000-0000-000000000010', 'A', 'Reassure the patient that this will resolve spontaneously once the swelling settles', false, 'Ruled out because paraphimosis does not resolve spontaneously and risks progressive ischaemia of the glans if the constricting band is not reduced; it requires prompt intervention.', 1),
('e4000000-0000-0000-0000-000000000010', 'B', 'Attempt urgent manual reduction, using analgesia and ice or lubrication, with surgical referral if unsuccessful', true, 'Correct. Paraphimosis is a urological emergency where the retracted foreskin cannot be returned over the glans, causing venous congestion that can progress to arterial compromise and necrosis if untreated. Initial management is manual reduction with adequate analgesia (and adjuncts such as ice, lubricant or osmotic agents); if this fails, urgent surgical intervention (dorsal slit or emergency circumcision) is required.', 2),
('e4000000-0000-0000-0000-000000000010', 'C', 'Advise the patient to retract the foreskin further to relieve the pressure', false, 'Ruled out because further retraction would worsen the constriction; the correct emergency action is to reduce the paraphimosis by returning the foreskin over the glans, not retract it further.', 3),
('e4000000-0000-0000-0000-000000000010', 'D', 'Start broad-spectrum oral antibiotics and discharge with outpatient urology follow-up', false, 'Ruled out because paraphimosis is a mechanical emergency requiring immediate reduction, not an infective process; discharge without addressing the constriction risks glans necrosis.', 4),
('e4000000-0000-0000-0000-000000000010', 'E', 'Apply a urinary catheter and send the patient home to await elective circumcision', false, 'Ruled out because this does not address the acute vascular compromise of the glans; the paraphimosis must be reduced urgently rather than deferred to an elective procedure.', 5),
('e4000000-0000-0000-0000-000000000011', 'A', 'Start an ACE inhibitor (e.g. ramipril) titrated as tolerated, alongside blood pressure control', true, 'Correct. In CKD with significant proteinuria (ACR greater than 30 mg/mmol), particularly in the context of diabetes, ACE inhibitors (or ARBs if not tolerated) reduce intraglomerular pressure and proteinuria, slowing progression of kidney disease, in addition to their antihypertensive effect. Renal function and potassium should be monitored after initiation.', 1),
('e4000000-0000-0000-0000-000000000011', 'B', 'Start a high-dose loop diuretic to preserve residual renal function', false, 'Ruled out because loop diuretics have no proven role in slowing CKD progression; they are used for fluid overload, which is not present here, and would not address her proteinuria or renoprotection needs.', 2),
('e4000000-0000-0000-0000-000000000011', 'C', 'Advise a low-protein diet as the primary intervention and defer any medication changes', false, 'Ruled out because pharmacological renoprotection (ACE inhibitor/ARB) with proteinuria reduction is the key intervention; while protein intake may be discussed as part of overall dietary advice, it is not the primary evidence-based measure here.', 3),
('e4000000-0000-0000-0000-000000000011', 'D', 'Refer for urgent renal biopsy before starting any new treatment', false, 'Ruled out because in a patient with long-standing diabetes, hypertension, and a typical pattern of proteinuric CKD, biopsy is not routinely required; standard renoprotective treatment should be started based on the clinical picture.', 4),
('e4000000-0000-0000-0000-000000000011', 'E', 'Stop amlodipine and start no replacement antihypertensive', false, 'Ruled out because uncontrolled blood pressure accelerates CKD progression; stopping antihypertensive treatment without replacement would be harmful, not protective.', 5),
('e4000000-0000-0000-0000-000000000012', 'A', 'Primary parathyroid adenoma causing autonomous PTH secretion', false, 'Ruled out because primary hyperparathyroidism typically causes hypercalcaemia with a low or low-normal phosphate, whereas this patient has a low-normal calcium and raised phosphate in the context of CKD, consistent with secondary rather than primary hyperparathyroidism.', 1),
('e4000000-0000-0000-0000-000000000012', 'B', 'Excess dietary calcium intake suppressing renal phosphate handling', false, 'Ruled out because there is no indication of excess calcium intake, and this would not explain the biochemical pattern of low-normal calcium, raised phosphate and elevated PTH seen in CKD-related bone disease.', 2),
('e4000000-0000-0000-0000-000000000012', 'C', 'Vitamin D toxicity from over-supplementation', false, 'Ruled out because vitamin D toxicity typically causes hypercalcaemia and hyperphosphataemia with suppressed PTH, which is the opposite pattern to that described, where PTH is markedly elevated (secondary hyperparathyroidism) alongside low-normal calcium.', 3),
('e4000000-0000-0000-0000-000000000012', 'D', 'Reduced renal phosphate excretion and impaired activation of vitamin D lead to hyperphosphataemia, hypocalcaemia and compensatory secondary hyperparathyroidism', true, 'Correct. In CKD, declining nephron mass reduces phosphate excretion (causing hyperphosphataemia) and reduces renal 1-alpha-hydroxylase activity needed to convert vitamin D to its active form, calcitriol. This reduces intestinal calcium absorption, contributing to low calcium, which together with hyperphosphataemia drives a compensatory rise in parathyroid hormone (secondary hyperparathyroidism), a key feature of CKD-mineral and bone disorder (CKD-MBD).', 4),
('e4000000-0000-0000-0000-000000000012', 'E', 'Increased renal 1-alpha-hydroxylase activity increasing active vitamin D production', false, 'Ruled out because CKD causes reduced, not increased, renal 1-alpha-hydroxylase activity, leading to less active vitamin D (calcitriol) and consequent hypocalcaemia driving secondary hyperparathyroidism.', 5),
('e4000000-0000-0000-0000-000000000013', 'A', 'Iron deficiency due to chronic gastrointestinal blood loss', false, 'Ruled out because her ferritin and transferrin saturation are within normal/replete ranges and stool occult blood testing is negative, making iron deficiency from bleeding unlikely as the primary cause.', 1),
('e4000000-0000-0000-0000-000000000013', 'B', 'Reduced erythropoietin production by the diseased kidneys', true, 'Correct. As nephron mass declines in CKD, erythropoietin production by peritubular cells falls, leading to a normocytic, normochromic anaemia. Iron studies here are replete (adequate ferritin and transferrin saturation), and there is no evidence of bleeding, making erythropoietin deficiency the most likely cause; treatment involves ensuring adequate iron stores before considering erythropoiesis-stimulating agents.', 2),
('e4000000-0000-0000-0000-000000000013', 'C', 'Vitamin B12 deficiency causing a macrocytic anaemia', false, 'Ruled out because her MCV is normal, not raised, which would be expected in B12 deficiency; the anaemia of CKD is typically normocytic.', 3),
('e4000000-0000-0000-0000-000000000013', 'D', 'Bone marrow infiltration by malignancy', false, 'Ruled out because there is nothing in this history to suggest malignancy or marrow infiltration, and anaemia of CKD from erythropoietin deficiency is a far more common and directly explicable cause in this context.', 4),
('e4000000-0000-0000-0000-000000000013', 'E', 'Haemolysis due to an autoimmune process', false, 'Ruled out because there are no features suggestive of haemolysis (e.g. no mention of raised bilirubin, LDH, or reticulocytosis), and the clinical context of declining renal function best explains a normocytic anaemia through erythropoietin deficiency.', 5),
('e4000000-0000-0000-0000-000000000014', 'A', 'Reassure the patient that this is expected progression of CKD and continue routine annual monitoring', false, 'Ruled out because this represents an unexpectedly rapid decline in eGFR with a large rise in proteinuria, which meets criteria for specialist referral to look for a treatable underlying cause, rather than simply being attributed to expected slow CKD progression.', 1),
('e4000000-0000-0000-0000-000000000014', 'B', 'Stop the ACE inhibitor immediately as the presumed cause of the deterioration', false, 'Ruled out because there is no indication the ACE inhibitor is causing this; blood pressure is well controlled and the marked rise in proteinuria and rapid eGFR decline suggest a new or progressive renal pathology needing specialist assessment, not simply drug withdrawal.', 2),
('e4000000-0000-0000-0000-000000000014', 'C', 'Refer urgently to nephrology for further assessment', true, 'Correct. A sustained decrease in eGFR of 25% or more with a change in CKD category, or a rapid decline in eGFR (more than 15 mL/min/1.73m2 within 12 months), along with a marked rise in ACR to the nephrotic range, are recognised indications for specialist nephrology referral to investigate for a superimposed or new renal pathology rather than simple CKD progression.', 3),
('e4000000-0000-0000-0000-000000000014', 'D', 'Increase the dose of ramipril and review again in six months', false, 'Ruled out because this rate of decline and rise in proteinuria warrants prompt specialist referral now, not a further six-month delay with a medication adjustment alone.', 4),
('e4000000-0000-0000-0000-000000000014', 'E', 'Arrange a renal ultrasound only, with no further referral needed', false, 'Ruled out because while imaging may be part of the work-up, this degree of rapid deterioration and rising proteinuria meets criteria for urgent nephrology referral for comprehensive assessment, not imaging in isolation.', 5),
('e4000000-0000-0000-0000-000000000015', 'A', 'All patients with CKD stage 3 will eventually require dialysis if they live long enough', false, 'Ruled out because many patients with CKD, especially stage 3, remain stable for years or never progress to end-stage renal disease, particularly with good blood pressure and risk factor control; progression is variable and not inevitable.', 1),
('e4000000-0000-0000-0000-000000000015', 'B', 'CKD has no effect on cardiovascular risk and can be managed independently of cardiovascular risk factors', false, 'Ruled out because CKD is a well-established independent risk factor for cardiovascular disease, and managing cardiovascular risk factors is an essential part of CKD management.', 2),
('e4000000-0000-0000-0000-000000000015', 'C', 'Dialysis should be started as soon as a patient reaches stage 3 CKD to prevent further decline', false, 'Ruled out because dialysis is reserved for end-stage renal disease (typically stage 5, or symptomatic stage 4/5) with specific indications; starting dialysis at stage 3 would be inappropriate and not evidence-based.', 3),
('e4000000-0000-0000-0000-000000000015', 'D', 'Blood pressure control has no impact on the rate of progression of CKD', false, 'Ruled out because good blood pressure control is one of the most important modifiable factors in slowing progression of CKD, alongside proteinuria reduction.', 4),
('e4000000-0000-0000-0000-000000000015', 'E', 'CKD is an independent risk factor for cardiovascular disease, and cardiovascular events are more common than progression to end-stage renal disease in most CKD patients', true, 'Correct. CKD is associated with a substantially increased risk of cardiovascular disease, and in many patients with earlier-stage CKD, death from cardiovascular causes is more likely to occur than progression to end-stage renal disease requiring dialysis. This is why cardiovascular risk factor management (blood pressure, lipids, smoking cessation) is a core part of CKD care.', 5),
('e4000000-0000-0000-0000-000000000016', 'A', 'Inhibition of prostaglandin-mediated afferent arteriolar vasodilation, reducing glomerular perfusion', true, $x$Correct. NSAIDs inhibit cyclo-oxygenase, reducing renal prostaglandin synthesis. Prostaglandins normally cause afferent arteriolar vasodilation to maintain glomerular filtration during states of reduced renal perfusion (such as volume depletion from gastroenteritis). Losing this compensatory mechanism, especially alongside an ACE inhibitor (which dilates the efferent arteriole) and a diuretic (which causes volume depletion) — the 'triple whammy' — significantly increases AKI risk.$x$, 1),
('e4000000-0000-0000-0000-000000000016', 'B', 'Direct toxic effect on the renal tubular epithelium causing acute tubular necrosis independent of haemodynamics', false, 'Ruled out because while NSAIDs can rarely cause interstitial nephritis or other direct renal injury, the principal and most common mechanism of NSAID-associated AKI in this setting is haemodynamically mediated through reduced prostaglandin-driven afferent arteriolar dilation, not direct tubular toxicity.', 2),
('e4000000-0000-0000-0000-000000000016', 'C', 'Formation of insoluble crystals that obstruct the renal tubules', false, 'Ruled out because crystal-induced tubular obstruction is a mechanism associated with drugs like acyclovir or methotrexate at high doses, not typically with NSAID-induced AKI.', 3),
('e4000000-0000-0000-0000-000000000016', 'D', 'Immune-mediated glomerular basement membrane damage', false, 'Ruled out because this describes a mechanism relevant to conditions like anti-GBM disease, not the haemodynamic mechanism by which NSAIDs precipitate AKI in volume-depleted patients.', 4),
('e4000000-0000-0000-0000-000000000016', 'E', 'Osmotic diuresis leading to profound dehydration', false, 'Ruled out because NSAIDs do not cause an osmotic diuresis; the relevant mechanism here is loss of prostaglandin-mediated renal autoregulation in the context of pre-existing volume depletion.', 5),
('e4000000-0000-0000-0000-000000000017', 'A', 'Direct toxic injury to the glomerular basement membrane by the ACE inhibitor', false, 'Ruled out because ACE inhibitors do not directly damage the glomerular basement membrane; the mechanism of AKI in renal artery stenosis is haemodynamic, related to loss of efferent arteriolar tone.', 1),
('e4000000-0000-0000-0000-000000000017', 'B', 'Loss of efferent arteriolar vasoconstriction critical for maintaining glomerular filtration pressure distal to the stenosis', true, 'Correct. In bilateral renal artery stenosis, glomerular filtration pressure downstream of the stenosis is critically dependent on angiotensin II-mediated efferent arteriolar vasoconstriction. ACE inhibitors block this compensatory mechanism, causing a sharp fall in glomerular filtration pressure and a significant rise in creatinine, which is a recognised and important reason to check renal function shortly after starting ACE inhibitors/ARBs.', 2),
('e4000000-0000-0000-0000-000000000017', 'C', 'Acute interstitial nephritis triggered by a hypersensitivity reaction to the drug', false, 'Ruled out because although ACE inhibitors can rarely cause interstitial nephritis, the clinical context here (known bilateral renal artery stenosis, rapid creatinine rise with improved blood pressure) is classic for haemodynamically mediated AKI, not an allergic interstitial process.', 3),
('e4000000-0000-0000-0000-000000000017', 'D', 'Rhabdomyolysis secondary to the new medication', false, 'Ruled out because ACE inhibitors are not associated with rhabdomyolysis, and there is nothing in the history (e.g. muscle pain, myoglobinuria) to suggest this diagnosis.', 4),
('e4000000-0000-0000-0000-000000000017', 'E', 'Worsening of pre-existing diabetic nephropathy unrelated to the new drug', false, 'Ruled out because the temporal relationship (creatinine rising sharply within a week of starting the ACE inhibitor) and known bilateral renal artery stenosis point clearly to a drug-related haemodynamic cause rather than coincidental progression of unrelated kidney disease.', 5),
('e4000000-0000-0000-0000-000000000018', 'A', 'An IgE-mediated hypersensitivity reaction causing acute interstitial nephritis', false, $x$Ruled out because the presence of granular casts is more typical of acute tubular necrosis, whereas interstitial nephritis classically shows white cell casts and features such as eosinophilia, fever and rash, which are not described here; gentamicin's major renal risk is direct tubular toxicity rather than hypersensitivity.$x$, 1),
('e4000000-0000-0000-0000-000000000018', 'B', 'Crystal nephropathy from precipitation of the drug within renal tubules', false, 'Ruled out because gentamicin does not typically cause crystal nephropathy; this mechanism is more associated with drugs such as high-dose aciclovir or sulfonamides.', 2),
('e4000000-0000-0000-0000-000000000018', 'C', 'Direct toxic accumulation of gentamicin in proximal tubular cells causing acute tubular necrosis', true, $x$Correct. Aminoglycosides such as gentamicin accumulate in proximal tubular epithelial cells and cause dose- and duration-dependent direct tubular toxicity, leading to acute tubular necrosis. Granular ('muddy brown') casts on urine microscopy support tubular injury, and risk increases with prolonged courses, higher doses, and pre-existing renal impairment or dehydration.$x$, 3),
('e4000000-0000-0000-0000-000000000018', 'D', 'Rhabdomyolysis-induced myoglobin cast nephropathy', false, $x$Ruled out because there is no clinical evidence of muscle breakdown (no mention of muscle pain, elevated CK) and gentamicin's known nephrotoxic mechanism is direct tubular cell toxicity, not causing rhabdomyolysis.$x$, 4),
('e4000000-0000-0000-0000-000000000018', 'E', 'Obstructive uropathy from drug-induced crystalluria causing bilateral ureteric obstruction', false, 'Ruled out because there is no imaging or clinical evidence of obstruction, and gentamicin nephrotoxicity classically presents as direct tubular toxicity rather than an obstructive process.', 5),
('e4000000-0000-0000-0000-000000000019', 'A', 'Acute tubular necrosis from direct nephrotoxicity', false, 'Ruled out because acute tubular necrosis typically presents with granular casts rather than white cell casts, and does not classically feature fever, rash and eosinophilia, which instead point towards a hypersensitivity-mediated interstitial nephritis.', 1),
('e4000000-0000-0000-0000-000000000019', 'B', 'Post-streptococcal glomerulonephritis', false, 'Ruled out because post-streptococcal glomerulonephritis typically presents with haematuria, hypertension and oedema following a streptococcal throat or skin infection, with red cell casts on urinalysis, rather than the sterile pyuria and white cell casts with systemic hypersensitivity features seen here.', 2),
('e4000000-0000-0000-0000-000000000019', 'C', 'Rhabdomyolysis-associated kidney injury', false, 'Ruled out because there is no evidence of muscle injury (no muscle pain or elevated CK mentioned), and the clinical picture (fever, rash, eosinophilia, white cell casts) is characteristic of a drug hypersensitivity reaction, not rhabdomyolysis.', 3),
('e4000000-0000-0000-0000-000000000019', 'D', 'Acute interstitial nephritis secondary to flucloxacillin', true, 'Correct. The triad of fever, rash and eosinophilia, together with sterile pyuria, white cell casts and a temporal relationship to a new antibiotic, is classic for drug-induced acute interstitial nephritis, a hypersensitivity reaction to the causative drug. Management involves stopping the offending drug promptly; corticosteroids may be considered in severe or persistent cases.', 4),
('e4000000-0000-0000-0000-000000000019', 'E', 'Obstructive uropathy due to a ureteric stone', false, 'Ruled out because there is no evidence of loin pain, haematuria typical of stones, or imaging findings of obstruction; the systemic hypersensitivity features and urinalysis findings point to interstitial nephritis instead.', 5),
('e4000000-0000-0000-0000-000000000020', 'A', 'Restricting fluids for 24 hours before the scan to reduce cardiac workload', false, 'Ruled out because fluid restriction increases the risk of contrast-induced nephropathy by promoting volume depletion; adequate hydration, not restriction, is protective.', 1),
('e4000000-0000-0000-0000-000000000020', 'B', 'Giving a prophylactic dose of gentamicin before the scan', false, 'Ruled out because gentamicin is itself nephrotoxic and has no role in preventing contrast-induced nephropathy; it would add to, not reduce, renal risk.', 2),
('e4000000-0000-0000-0000-000000000020', 'C', 'Administering a loop diuretic immediately before contrast injection', false, 'Ruled out because diuretics can cause volume depletion, which increases the risk of contrast-induced nephropathy rather than protecting against it.', 3),
('e4000000-0000-0000-0000-000000000020', 'D', 'Using the highest possible contrast volume to ensure adequate image quality', false, 'Ruled out because minimising, not maximising, the volume and osmolality of contrast used reduces the risk of contrast-induced nephropathy; the lowest dose needed for diagnostic quality should be used.', 4),
('e4000000-0000-0000-0000-000000000020', 'E', 'Ensuring adequate intravenous hydration with isotonic fluids before and after the scan', true, 'Correct. Adequate periprocedural intravenous hydration with isotonic fluids is the most evidence-supported and widely used measure to reduce the risk of contrast-induced nephropathy in at-risk patients, by maintaining renal perfusion and helping to flush contrast media through the kidneys.', 5),
('e4000000-0000-0000-0000-000000000021', 'A', 'Reassure the patient and recheck potassium in one week, as he is asymptomatic', false, 'Ruled out because ECG changes of hyperkalaemia indicate significant cardiac risk regardless of symptoms; this requires urgent treatment, not simply a delayed recheck.', 1),
('e4000000-0000-0000-0000-000000000021', 'B', 'Start an oral potassium-binding resin as the sole treatment and discharge home', false, 'Ruled out because potassium-binding resins act slowly over hours to days and do not provide the rapid myocardial protection needed when ECG changes are present with this degree of hyperkalaemia.', 2),
('e4000000-0000-0000-0000-000000000021', 'C', 'Give intravenous calcium gluconate to stabilise the myocardium, followed by insulin-dextrose to lower serum potassium', true, 'Correct. Significant hyperkalaemia (potassium greater than 6.5 mmol/L) with ECG changes (tall tented T waves) requires urgent treatment even in an asymptomatic patient, as this indicates a risk of progression to life-threatening arrhythmia. IV calcium gluconate stabilises the cardiac membrane, and insulin-dextrose subsequently shifts potassium intracellularly to lower serum levels.', 3),
('e4000000-0000-0000-0000-000000000021', 'D', 'Give intravenous sodium bicarbonate as first-line treatment for the hyperkalaemia', false, 'Ruled out because sodium bicarbonate is not first-line treatment for hyperkalaemia in this context (it has a limited and now less favoured role, generally reserved for hyperkalaemia with severe concurrent metabolic acidosis); calcium gluconate followed by insulin-dextrose is the standard emergency approach.', 4),
('e4000000-0000-0000-0000-000000000021', 'E', 'Restrict oral fluids and reassess renal function in 48 hours', false, 'Ruled out because this does not address the acute risk of hyperkalaemia-related arrhythmia; the ECG changes indicate this needs immediate emergency treatment, not observation over 48 hours.', 5),
('e4000000-0000-0000-0000-000000000022', 'A', $x$Primary adrenal insufficiency (Addison's disease)$x$, false, 'Ruled out because adrenal insufficiency is typically associated with hyperkalaemia and hypovolaemia, and the question states adrenal function is normal, making this an unlikely cause of her euvolaemic hyponatraemia.', 1),
('e4000000-0000-0000-0000-000000000022', 'B', 'Diuretic-induced hyponatraemia', false, 'Ruled out because there is no mention of diuretic use, and the clinical and biochemical picture (euvolaemic, malignancy-associated, concentrated urine) is more consistent with SIADH from ectopic ADH secretion by the tumour.', 2),
('e4000000-0000-0000-0000-000000000022', 'C', 'Psychogenic polydipsia', false, 'Ruled out because psychogenic polydipsia typically causes hyponatraemia through excessive water intake with appropriately dilute urine (low urine osmolality), which is the opposite of the inappropriately concentrated urine described here.', 3),
('e4000000-0000-0000-0000-000000000022', 'D', 'Syndrome of inappropriate antidiuretic hormone secretion (SIADH) secondary to her lung cancer', true, 'Correct. Small cell lung cancer is a well-recognised cause of ectopic ADH secretion, leading to SIADH. This presents with euvolaemic hyponatraemia, inappropriately concentrated urine (high urine osmolality) despite low plasma osmolality, elevated urine sodium, and normal thyroid and adrenal function, which excludes other common causes of hyponatraemia.', 4),
('e4000000-0000-0000-0000-000000000022', 'E', 'Hypothyroidism', false, 'Ruled out because thyroid function is stated to be normal, and while hypothyroidism can rarely cause hyponatraemia, it is excluded here by normal thyroid function tests.', 5),
('e4000000-0000-0000-0000-000000000023', 'A', 'Syndrome of inappropriate antidiuretic hormone secretion', false, 'Ruled out because SIADH causes hyponatraemia with concentrated urine, which is the opposite biochemical picture to the hypernatraemia and dilute urine seen in this patient.', 1),
('e4000000-0000-0000-0000-000000000023', 'B', 'Nephrogenic diabetes insipidus due to long-term lithium therapy', false, 'Ruled out because there is no mention of lithium use, and the acute onset following traumatic brain injury points to a cranial (central) rather than nephrogenic cause of diabetes insipidus.', 2),
('e4000000-0000-0000-0000-000000000023', 'C', 'Osmotic diuresis secondary to hyperglycaemia', false, 'Ruled out because there is no mention of hyperglycaemia, and osmotic diuresis from glucose would be expected to show glucose in the urine and a different clinical context, whereas here the picture (head injury, dilute urine, rising sodium) is classic for cranial DI.', 3),
('e4000000-0000-0000-0000-000000000023', 'D', 'Primary polydipsia causing dilutional hyponatraemia', false, 'Ruled out because primary polydipsia causes hyponatraemia through excess water intake, not the hypernatraemia and inappropriately dilute urine seen here in a patient who is not exhibiting excess intake but rather excessive water loss.', 4),
('e4000000-0000-0000-0000-000000000023', 'E', 'Cranial diabetes insipidus due to reduced antidiuretic hormone secretion following the head injury', true, 'Correct. Traumatic brain injury can damage the hypothalamic-pituitary axis, reducing ADH secretion and causing cranial diabetes insipidus. This presents with polyuria of dilute urine (low urine osmolality) despite rising plasma osmolality and hypernatraemia, because the kidneys cannot concentrate urine appropriately without ADH.', 5),
('e4000000-0000-0000-0000-000000000024', 'A', 'Excessive dietary potassium intake', false, 'Ruled out because excessive potassium intake would tend to cause hyperkalaemia, not hypokalaemia, and does not explain her presentation.', 1),
('e4000000-0000-0000-0000-000000000024', 'B', 'Thiazide diuretic-induced renal potassium loss', true, 'Correct. Thiazide diuretics increase distal tubular sodium delivery, promoting potassium secretion and urinary loss, which can cause significant hypokalaemia, particularly with long-term use. The clinical features (weakness, constipation) and ECG findings (flattened T waves, prominent U waves) are typical of hypokalaemia.', 2),
('e4000000-0000-0000-0000-000000000024', 'C', $x$Adrenal insufficiency (Addison's disease)$x$, false, 'Ruled out because adrenal insufficiency typically causes hyperkalaemia (due to reduced aldosterone) rather than hypokalaemia, which is the opposite of what is seen here.', 3),
('e4000000-0000-0000-0000-000000000024', 'D', 'Acute kidney injury with reduced potassium excretion', false, 'Ruled out because AKI with reduced excretory capacity typically causes hyperkalaemia, not hypokalaemia; the clinical context here (long-term thiazide use) directly explains renal potassium loss instead.', 4),
('e4000000-0000-0000-0000-000000000024', 'E', 'Rhabdomyolysis releasing potassium into the circulation', false, 'Ruled out because rhabdomyolysis causes hyperkalaemia from cellular potassium release, not hypokalaemia, and there is no supporting history of muscle injury.', 5),
('e4000000-0000-0000-0000-000000000025', 'A', 'Intravenous 0.9% sodium chloride to rehydrate, followed by an intravenous bisphosphonate', true, 'Correct. Severe hypercalcaemia of malignancy is a medical emergency. Initial management is aggressive rehydration with intravenous 0.9% sodium chloride to improve renal calcium excretion and correct dehydration, followed by an intravenous bisphosphonate (e.g. zoledronic acid) to reduce osteoclast-mediated bone resorption and lower calcium over the following days.', 1),
('e4000000-0000-0000-0000-000000000025', 'B', 'Restrict fluids and give a thiazide diuretic to reduce calcium levels', false, 'Ruled out because thiazide diuretics increase calcium reabsorption and would worsen hypercalcaemia, and fluid restriction would worsen her dehydration; rehydration and calcium-lowering therapy are needed instead.', 2),
('e4000000-0000-0000-0000-000000000025', 'C', 'Give a loop diuretic as first-line treatment before any fluid resuscitation', false, 'Ruled out because loop diuretics should not be given before adequate rehydration, as they can worsen volume depletion; rehydration with saline comes first, and loop diuretics are not first-line for hypercalcaemia of malignancy.', 3),
('e4000000-0000-0000-0000-000000000025', 'D', 'Start oral calcium supplementation to stabilise cell membranes', false, 'Ruled out because giving additional calcium would worsen the severe hypercalcaemia and is directly contraindicated in this emergency.', 4),
('e4000000-0000-0000-0000-000000000025', 'E', 'Arrange elective outpatient endocrinology review in two weeks', false, 'Ruled out because this degree of hypercalcaemia (corrected calcium 3.4 mmol/L) with confusion is a medical emergency requiring immediate inpatient treatment, not delayed outpatient review.', 5),
('e4000000-0000-0000-0000-000000000026', 'A', 'Post-streptococcal glomerulonephritis', false, 'Ruled out because post-streptococcal glomerulonephritis presents as a nephritic picture with haematuria, hypertension, and mild proteinuria, rather than the heavy proteinuria, hypoalbuminaemia and oedema of nephrotic syndrome seen here.', 1),
('e4000000-0000-0000-0000-000000000026', 'B', 'IgA nephropathy', false, 'Ruled out because IgA nephropathy classically presents with episodic macroscopic haematuria, often following an upper respiratory tract infection, rather than a nephrotic syndrome picture.', 2),
('e4000000-0000-0000-0000-000000000026', 'C', 'Minimal change disease', true, 'Correct. Minimal change disease is the most common cause of nephrotic syndrome in children, presenting with the classic triad of heavy proteinuria, hypoalbuminaemia, and oedema, typically without haematuria or significant renal impairment. It is usually highly steroid-responsive.', 3),
('e4000000-0000-0000-0000-000000000026', 'D', 'Rapidly progressive glomerulonephritis', false, 'Ruled out because rapidly progressive glomerulonephritis presents with a rapid decline in renal function and often haematuria, rather than the isolated nephrotic syndrome picture with preserved renal function described here.', 4),
('e4000000-0000-0000-0000-000000000026', 'E', 'Diabetic nephropathy', false, 'Ruled out because there is no history of diabetes, and diabetic nephropathy typically develops after years of poorly controlled diabetes, which is not applicable to this five-year-old.', 5),
('e4000000-0000-0000-0000-000000000027', 'A', 'Post-streptococcal glomerulonephritis', false, 'Ruled out because post-streptococcal glomerulonephritis typically causes a single episode of haematuria one to three weeks after a streptococcal throat or skin infection (a latent interval), rather than recurrent episodes occurring immediately with each viral illness.', 1),
('e4000000-0000-0000-0000-000000000027', 'B', 'Minimal change disease', false, 'Ruled out because minimal change disease presents with nephrotic syndrome (heavy proteinuria, hypoalbuminaemia, oedema) rather than recurrent macroscopic haematuria linked to upper respiratory infections.', 2),
('e4000000-0000-0000-0000-000000000027', 'C', 'Alport syndrome', false, 'Ruled out because Alport syndrome is an inherited condition typically presenting with persistent microscopic haematuria, progressive renal impairment, sensorineural hearing loss, and a family history, rather than recurrent episodic macroscopic haematuria with viral illnesses.', 3),
('e4000000-0000-0000-0000-000000000027', 'D', 'IgA nephropathy', true, $x$Correct. IgA nephropathy classically presents with episodes of macroscopic (visible) haematuria occurring synchronously with or shortly after an upper respiratory tract infection ('synpharyngitic' haematuria), often in young adults, and can recur with subsequent infections. It is the most common primary glomerulonephritis worldwide.$x$, 4),
('e4000000-0000-0000-0000-000000000027', 'E', 'Bladder cancer', false, 'Ruled out because bladder cancer typically presents with painless haematuria in an older patient, often with risk factors such as smoking, and does not classically occur in temporal relation to viral upper respiratory infections in a young adult.', 5),
('e4000000-0000-0000-0000-000000000028', 'A', 'Minimal change disease', false, 'Ruled out because minimal change disease presents with a nephrotic (not nephritic) picture: heavy proteinuria, hypoalbuminaemia and oedema, typically without haematuria, red cell casts, or the preceding streptococcal infection history described here.', 1),
('e4000000-0000-0000-0000-000000000028', 'B', 'Post-streptococcal glomerulonephritis', true, 'Correct. This presentation, occurring one to three weeks after a streptococcal throat infection with haematuria (tea-coloured urine), red cell casts, hypertension, oedema and mild renal impairment, is classic for post-streptococcal glomerulonephritis, an immune complex-mediated nephritic syndrome that typically resolves with supportive management in children.', 2),
('e4000000-0000-0000-0000-000000000028', 'C', 'IgA nephropathy', false, 'Ruled out because IgA nephropathy typically causes haematuria occurring simultaneously with a respiratory infection (synpharyngitic), rather than after a latent period of one to three weeks as seen with post-streptococcal glomerulonephritis.', 3),
('e4000000-0000-0000-0000-000000000028', 'D', 'Membranous nephropathy', false, 'Ruled out because membranous nephropathy presents with a nephrotic syndrome picture, usually in adults, and is not typically preceded by a streptococcal infection.', 4),
('e4000000-0000-0000-0000-000000000028', 'E', 'Henoch-Schonlein purpura without renal involvement', false, 'Ruled out because there is no mention of the characteristic purpuric rash, joint pain, or abdominal pain of Henoch-Schonlein purpura, and this presentation with recent streptococcal infection and nephritic features is more consistent with post-streptococcal glomerulonephritis.', 5),
('e4000000-0000-0000-0000-000000000029', 'A', 'Urgent referral to nephrology for plasma exchange and immunosuppression (corticosteroids and cyclophosphamide)', true, 'Correct. This presentation of pulmonary haemorrhage with rapidly progressive glomerulonephritis and positive anti-GBM antibodies is consistent with anti-glomerular basement membrane disease (Goodpasture syndrome). This is a medical emergency requiring urgent specialist referral for plasma exchange to remove circulating antibodies, combined with immunosuppression (corticosteroids and cyclophosphamide) to prevent further antibody production and preserve renal and pulmonary function.', 1),
('e4000000-0000-0000-0000-000000000029', 'B', 'Reassurance and outpatient follow-up in two weeks, as symptoms often resolve spontaneously', false, 'Ruled out because anti-GBM disease is a rapidly progressive, life- and organ-threatening condition that requires immediate specialist treatment; it does not resolve spontaneously and delay risks irreversible renal failure and life-threatening pulmonary haemorrhage.', 2),
('e4000000-0000-0000-0000-000000000029', 'C', 'Start oral antibiotics for presumed community-acquired pneumonia', false, 'Ruled out because the combination of positive anti-GBM antibodies, red cell casts, and rapidly progressive renal failure points to an autoimmune vasculitic process rather than infection, and antibiotics alone would not address the underlying disease.', 3),
('e4000000-0000-0000-0000-000000000029', 'D', 'Commence a course of oral prednisolone alone without other measures', false, 'Ruled out because oral corticosteroids alone are insufficient for this severe presentation; the standard of care combines plasma exchange with combination immunosuppression to rapidly reduce antibody levels and prevent further organ damage.', 4),
('e4000000-0000-0000-0000-000000000029', 'E', 'Arrange elective renal biopsy in six weeks to confirm the diagnosis before starting treatment', false, 'Ruled out because this condition can progress to irreversible renal failure and life-threatening pulmonary haemorrhage within days; treatment should not be delayed for elective biopsy given a strongly supportive clinical and serological picture.', 5),
('e4000000-0000-0000-0000-000000000030', 'A', 'Minimal change disease', false, $x$Ruled out because minimal change disease shows normal-appearing glomeruli on light microscopy with only foot process effacement on electron microscopy, not the basement membrane thickening and 'spike and dome' pattern described here.$x$, 1),
('e4000000-0000-0000-0000-000000000030', 'B', 'Diabetic nephropathy', false, $x$Ruled out because there is no history of diabetes, and diabetic nephropathy typically shows characteristic nodular glomerulosclerosis (Kimmelstiel-Wilson nodules) rather than the 'spike and dome' pattern of membranous nephropathy.$x$, 2),
('e4000000-0000-0000-0000-000000000030', 'C', 'IgA nephropathy', false, $x$Ruled out because IgA nephropathy typically presents with haematuria and shows mesangial IgA deposition on biopsy, rather than the diffuse basement membrane thickening with 'spike and dome' appearance seen in membranous nephropathy.$x$, 3),
('e4000000-0000-0000-0000-000000000030', 'D', 'Focal segmental glomerulosclerosis', false, $x$Ruled out because focal segmental glomerulosclerosis shows segmental scarring of glomeruli on light microscopy, a different histological pattern from the diffuse basement membrane thickening and 'spike and dome' appearance of membranous nephropathy.$x$, 4),
('e4000000-0000-0000-0000-000000000030', 'E', 'Membranous nephropathy', true, $x$Correct. Membranous nephropathy is a common cause of nephrotic syndrome in adults, characterised histologically by diffuse thickening of the glomerular basement membrane with subepithelial immune complex deposits producing the classic 'spike and dome' appearance on electron microscopy. It can be primary (often associated with anti-PLA2R antibodies) or secondary to conditions such as malignancy, infections, or autoimmune disease, which should be screened for.$x$, 5),
('e4000000-0000-0000-0000-000000000031', 'A', 'Calcineurin inhibitor (tacrolimus) toxicity', false, 'Ruled out because while tacrolimus toxicity can cause a rise in creatinine, it does not typically cause graft tenderness and fever, which are more suggestive of an inflammatory/rejection process requiring urgent biopsy to distinguish from toxicity.', 1),
('e4000000-0000-0000-0000-000000000031', 'B', $x$Recurrence of the patient's original kidney disease$x$, false, 'Ruled out because recurrent original disease typically causes a more gradual decline in graft function without the acute fever and graft tenderness described, which point more specifically towards acute rejection.', 2),
('e4000000-0000-0000-0000-000000000031', 'C', 'Acute transplant rejection', true, 'Correct. A rise in creatinine with graft tenderness and low-grade fever in a transplant recipient is a classic presentation of acute rejection (cellular or antibody-mediated). This requires urgent assessment, typically including a transplant biopsy to confirm the type of rejection and guide treatment (e.g. pulsed corticosteroids for cellular rejection, or plasma exchange/other therapies for antibody-mediated rejection).', 3),
('e4000000-0000-0000-0000-000000000031', 'D', 'Urinary tract infection with no effect on the transplanted kidney', false, 'Ruled out because a UTI alone would not typically explain the graft tenderness and significant rise in creatinine; these features raise concern for rejection directly affecting the transplanted kidney, which needs urgent evaluation.', 4),
('e4000000-0000-0000-0000-000000000031', 'E', 'Normal expected fluctuation in renal function after transplantation', false, 'Ruled out because a rise in creatinine of this magnitude with associated fever and graft tenderness is not a normal or expected finding and requires prompt investigation for rejection or another significant cause of graft dysfunction.', 5),
('e4000000-0000-0000-0000-000000000032', 'A', 'Acute transplant rejection triggered by the antibiotic', false, 'Ruled out because the clinical picture (markedly elevated tacrolimus level, tremor, confusion, rising creatinine shortly after starting a known interacting drug) is characteristic of drug-induced calcineurin inhibitor toxicity rather than rejection.', 1),
('e4000000-0000-0000-0000-000000000032', 'B', 'A new urinary tract infection causing systemic sepsis', false, 'Ruled out because the temporal relationship to starting clarithromycin and the markedly elevated tacrolimus level point specifically to a drug interaction causing toxicity, rather than an unrelated infective process.', 2),
('e4000000-0000-0000-0000-000000000032', 'C', 'Clarithromycin has induced increased metabolism of tacrolimus, leading to sub-therapeutic levels', false, 'Ruled out because clarithromycin inhibits, rather than induces, CYP3A4 metabolism of tacrolimus, leading to elevated (not reduced) tacrolimus levels, consistent with the toxic level found.', 3),
('e4000000-0000-0000-0000-000000000032', 'D', 'Clarithromycin has inhibited the metabolism of tacrolimus via cytochrome P450 3A4, causing tacrolimus toxicity', true, $x$Correct. Macrolide antibiotics such as clarithromycin are potent inhibitors of cytochrome P450 3A4, the main enzyme responsible for tacrolimus metabolism. This interaction can rapidly raise tacrolimus levels into the toxic range, causing neurotoxicity (tremor, confusion) and nephrotoxicity (rising creatinine). Transplant patients' medication changes should always be discussed with the transplant team, and interacting drugs should be avoided or doses adjusted with close monitoring.$x$, 4),
('e4000000-0000-0000-0000-000000000032', 'E', 'Coincidental idiopathic tremor unrelated to his medications', false, 'Ruled out because the markedly raised tacrolimus level in temporal association with starting a known CYP3A4 inhibitor provides a clear and specific explanation for his symptoms, rather than this being an unrelated idiopathic process.', 5),
('e4000000-0000-0000-0000-000000000033', 'A', 'Streptococcus pneumoniae', false, 'Ruled out because typical bacterial pneumonia from Streptococcus pneumoniae usually presents with lobar consolidation on chest X-ray rather than the bilateral diffuse ground-glass pattern described, and does not have the same specific link to missed co-trimoxazole prophylaxis.', 1),
('e4000000-0000-0000-0000-000000000033', 'B', 'Pneumocystis jirovecii', true, 'Correct. Pneumocystis jirovecii pneumonia is a recognised opportunistic infection in immunosuppressed transplant recipients, classically presenting with fever, dry cough, progressive breathlessness and bilateral ground-glass changes on chest imaging. Co-trimoxazole is used as prophylaxis in the early post-transplant period specifically to prevent this infection, and non-adherence increases risk.', 2),
('e4000000-0000-0000-0000-000000000033', 'C', 'Mycobacterium tuberculosis', false, 'Ruled out because while TB is a recognised risk in immunosuppressed patients, the acute presentation with bilateral ground-glass changes and the specific context of missed PJP prophylaxis is much more classic for Pneumocystis jirovecii.', 3),
('e4000000-0000-0000-0000-000000000033', 'D', 'Influenza virus', false, 'Ruled out because although influenza can cause bilateral pneumonitis, the specific clinical context of a transplant recipient who has missed co-trimoxazole prophylaxis points most directly to Pneumocystis jirovecii, which that prophylaxis is specifically designed to prevent.', 4),
('e4000000-0000-0000-0000-000000000033', 'E', 'Aspergillus fumigatus', false, 'Ruled out because invasive aspergillosis more typically causes nodular or cavitating lesions and occurs particularly with more profound or prolonged neutropenia/immunosuppression, whereas this presentation and the missed PJP-specific prophylaxis point to Pneumocystis jirovecii.', 5),
('e4000000-0000-0000-0000-000000000034', 'A', 'Acute transplant rejection presenting atypically with hyperglycaemia', false, 'Ruled out because acute rejection typically presents with a rise in creatinine and graft dysfunction, not with new hyperglycaemia; the clinical picture here (weight gain, immunosuppressant use, raised HbA1c) is classic for new-onset diabetes after transplantation.', 1),
('e4000000-0000-0000-0000-000000000034', 'B', 'Undiagnosed type 1 diabetes coincidentally presenting three years post-transplant', false, 'Ruled out because the clinical context (weight gain, use of diabetogenic immunosuppressants, gradual glucose rise) is far more consistent with new-onset diabetes related to transplant immunosuppression than a coincidental new type 1 diabetes diagnosis.', 2),
('e4000000-0000-0000-0000-000000000034', 'C', 'Cytomegalovirus infection causing pancreatic dysfunction', false, 'Ruled out because there is no clinical evidence of active CMV infection here, and the described metabolic pattern (weight gain, chronic immunosuppressant use, raised HbA1c) is explained directly by known diabetogenic effects of tacrolimus and steroids.', 3),
('e4000000-0000-0000-0000-000000000034', 'D', 'Graft-versus-host disease affecting the pancreas', false, 'Ruled out because graft-versus-host disease is not a recognised complication of solid organ (renal) transplantation; it is associated with haematopoietic stem cell transplantation, which is not relevant here.', 4),
('e4000000-0000-0000-0000-000000000034', 'E', 'New-onset diabetes after transplantation related to immunosuppressive therapy', true, 'Correct. Both tacrolimus and corticosteroids are recognised to increase the risk of new-onset diabetes after transplantation, through mechanisms including impaired insulin secretion (tacrolimus) and insulin resistance (corticosteroids), compounded by weight gain. This is a well-recognised long-term complication requiring monitoring and management, similar to type 2 diabetes.', 5),
('e4000000-0000-0000-0000-000000000035', 'A', 'Chronic allograft dysfunction (chronic rejection/interstitial fibrosis and tubular atrophy)', true, 'Correct. A slow, progressive decline in graft function over months to years, without an acute precipitant, fever or graft tenderness, and with therapeutic drug levels, is characteristic of chronic allograft dysfunction (previously termed chronic allograft nephropathy), reflecting a combination of chronic immune-mediated injury, calcineurin inhibitor nephrotoxicity, and other factors leading to interstitial fibrosis and tubular atrophy on biopsy. It should prompt nephrology/transplant review to look for reversible contributing factors and plan long-term management.', 1),
('e4000000-0000-0000-0000-000000000035', 'B', 'Acute cellular rejection', false, 'Ruled out because acute rejection typically presents with a more rapid rise in creatinine, often with graft tenderness and sometimes fever, rather than the slow, indolent decline over 18 months described here.', 2),
('e4000000-0000-0000-0000-000000000035', 'C', 'Acute tacrolimus toxicity', false, 'Ruled out because tacrolimus levels have been consistently within the therapeutic range, making acute toxicity from supratherapeutic levels an unlikely explanation for this gradual decline.', 3),
('e4000000-0000-0000-0000-000000000035', 'D', 'Urinary tract infection causing progressive graft damage', false, 'Ruled out because there is no fever or other evidence of infection described, and a slow progressive decline over 18 months is not typical of infection-related graft injury.', 4),
('e4000000-0000-0000-0000-000000000035', 'E', 'Renal artery stenosis of the transplant renal artery presenting acutely', false, 'Ruled out because although transplant renal artery stenosis can cause graft dysfunction and hypertension, it is not stated here, and the gradual, indolent pattern of decline over many months without other clues is more typical of chronic allograft dysfunction; renal artery stenosis should be considered in the differential and excluded on further work-up, particularly with imaging.', 5),
('e4000000-0000-0000-0000-000000000036', 'A', 'Simple renal cysts', false, 'Ruled out because simple renal cysts are usually solitary or few in number, do not cause bilateral kidney enlargement or a strong family history of renal failure, and are typically incidental findings without the clinical features described here.', 1),
('e4000000-0000-0000-0000-000000000036', 'B', 'Autosomal recessive polycystic kidney disease', false, 'Ruled out because autosomal recessive polycystic kidney disease typically presents in infancy or early childhood with severe disease, rather than being newly recognised in an adult with an autosomal dominant-pattern family history (parent affected).', 2),
('e4000000-0000-0000-0000-000000000036', 'C', 'Acquired cystic kidney disease secondary to long-term dialysis', false, 'Ruled out because there is no history of chronic kidney disease or dialysis in this patient himself; the family history and bilateral extensive cystic change point to an inherited condition (ADPKD) rather than acquired cysts from dialysis.', 3),
('e4000000-0000-0000-0000-000000000036', 'D', 'Von Hippel-Lindau syndrome', false, 'Ruled out because although Von Hippel-Lindau syndrome can cause renal cysts, it is also associated with other tumours (e.g. retinal and CNS haemangioblastomas, phaeochromocytoma, renal cell carcinoma) not described here, and the pattern of family history and presentation is much more typical of ADPKD.', 4),
('e4000000-0000-0000-0000-000000000036', 'E', 'Autosomal dominant polycystic kidney disease', true, 'Correct. The combination of a strong family history of kidney failure, hypertension, haematuria, bilateral palpable flank masses, and multiple bilateral renal cysts with enlarged kidneys on ultrasound is classic for autosomal dominant polycystic kidney disease (ADPKD), most commonly due to PKD1 or PKD2 mutations.', 5),
('e4000000-0000-0000-0000-000000000037', 'A', 'Type 2 (proximal) renal tubular acidosis', false, 'Ruled out because type 2 RTA results from impaired bicarbonate reabsorption in the proximal tubule and typically presents with a more acidic urine pH once the filtered bicarbonate load falls below the reduced reabsorptive threshold, and is less classically associated with nephrocalcinosis compared to distal RTA.', 1),
('e4000000-0000-0000-0000-000000000037', 'B', 'Type 4 renal tubular acidosis', false, 'Ruled out because type 4 RTA is associated with hyperkalaemia (due to aldosterone deficiency or resistance), which is the opposite of the hypokalaemia described in this patient.', 2),
('e4000000-0000-0000-0000-000000000037', 'C', 'Type 1 (distal) renal tubular acidosis', true, $x$Correct. Type 1 (distal) renal tubular acidosis results from an inability of the distal tubule to secrete hydrogen ions, causing a hyperchloraemic normal anion gap metabolic acidosis with an inappropriately alkaline urine pH (typically above 5.5) despite systemic acidosis, along with hypokalaemia and a tendency to nephrocalcinosis and kidney stones. It is associated with autoimmune conditions such as Sjogren's syndrome.$x$, 3),
('e4000000-0000-0000-0000-000000000037', 'D', 'Diabetic ketoacidosis', false, 'Ruled out because diabetic ketoacidosis causes a high anion gap metabolic acidosis with hyperglycaemia and ketosis, not the normal anion gap picture with nephrocalcinosis and an autoimmune association described here.', 4),
('e4000000-0000-0000-0000-000000000037', 'E', 'Chronic kidney disease-related metabolic acidosis', false, 'Ruled out because CKD-related acidosis typically occurs with significantly reduced eGFR and is often a high anion gap acidosis in advanced disease, rather than the classic hyperchloraemic normal anion gap picture with inappropriately alkaline urine and nephrocalcinosis seen in distal RTA.', 5),
('e4000000-0000-0000-0000-000000000038', 'A', 'Alport syndrome', true, 'Correct. Alport syndrome is a genetic disorder of type IV collagen, most commonly X-linked, presenting with persistent microscopic (and sometimes macroscopic) haematuria, progressive renal impairment, sensorineural hearing loss, and characteristic ocular abnormalities such as anterior lenticonus. The family history pattern (affected males more severely, with renal disease in maternal relatives) supports X-linked inheritance.', 1),
('e4000000-0000-0000-0000-000000000038', 'B', 'IgA nephropathy', false, 'Ruled out because while IgA nephropathy causes haematuria, it does not explain the combination of sensorineural hearing loss, lenticonus, and the specific family history pattern seen here, which are characteristic of Alport syndrome.', 2),
('e4000000-0000-0000-0000-000000000038', 'C', 'Thin basement membrane disease', false, 'Ruled out because thin basement membrane disease causes isolated persistent microscopic haematuria with a generally benign long-term prognosis, without the extra-renal features (hearing loss, lenticonus) or the progressive renal disease seen in affected relatives here.', 3),
('e4000000-0000-0000-0000-000000000038', 'D', 'Post-streptococcal glomerulonephritis', false, 'Ruled out because there is no history of a preceding streptococcal infection, and the chronic, familial pattern with sensorineural hearing loss and lenticonus points to a genetic diagnosis (Alport syndrome) rather than a post-infectious glomerulonephritis.', 4),
('e4000000-0000-0000-0000-000000000038', 'E', 'Minimal change disease', false, 'Ruled out because minimal change disease presents with nephrotic syndrome (heavy proteinuria, oedema), not with isolated haematuria, hearing loss, and eye findings as seen in this case.', 5),
('e4000000-0000-0000-0000-000000000039', 'A', 'Type 1 (distal) renal tubular acidosis', false, 'Ruled out because type 1 RTA causes an isolated defect in distal hydrogen ion secretion without the accompanying glucosuria, generalised aminoaciduria, and phosphate wasting seen in Fanconi syndrome.', 1),
('e4000000-0000-0000-0000-000000000039', 'B', 'Diabetes mellitus with diabetic nephropathy', false, 'Ruled out because blood glucose is stated to be normal, excluding diabetes mellitus as the cause of the glucosuria; the combination of aminoaciduria, phosphaturia, and acidosis instead points to generalised proximal tubular dysfunction (Fanconi syndrome).', 2),
('e4000000-0000-0000-0000-000000000039', 'C', 'Nephrogenic diabetes insipidus', false, 'Ruled out because nephrogenic diabetes insipidus causes polyuria due to resistance to ADH, without the glucosuria, generalised aminoaciduria, or phosphate wasting seen in this child.', 3),
('e4000000-0000-0000-0000-000000000039', 'D', 'Fanconi syndrome', true, 'Correct. Fanconi syndrome results from generalised proximal tubular dysfunction, causing combined glucosuria (with normal blood glucose), aminoaciduria, phosphaturia (leading to hypophosphataemia and rickets/osteomalacia), and a proximal (type 2) renal tubular acidosis. It can be inherited (e.g. cystinosis) or acquired (e.g. certain drugs, heavy metals, myeloma).', 4),
('e4000000-0000-0000-0000-000000000039', 'E', 'Bartter syndrome', false, 'Ruled out because Bartter syndrome is characterised by hypokalaemia, metabolic alkalosis and salt wasting due to a loop-of-Henle transport defect, which is a different biochemical pattern from the proximal tubular dysfunction (glucosuria, aminoaciduria, phosphaturia, acidosis) described here.', 5),
('e4000000-0000-0000-0000-000000000040', 'A', 'Cranial diabetes insipidus due to a pituitary lesion', false, $x$Ruled out because cranial diabetes insipidus typically shows a good response to administered desmopressin (urine osmolality rises significantly), whereas this patient's urine osmolality remained low despite desmopressin, indicating renal resistance to ADH (nephrogenic DI) rather than a lack of ADH secretion.$x$, 1),
('e4000000-0000-0000-0000-000000000040', 'B', 'Nephrogenic diabetes insipidus secondary to lithium therapy', true, 'Correct. Long-term lithium use is a well-recognised cause of nephrogenic diabetes insipidus, where the collecting ducts become resistant to the action of ADH, impairing urinary concentrating ability. This produces polyuria and polydipsia with persistently dilute urine that fails to respond adequately to exogenous desmopressin, distinguishing it from cranial diabetes insipidus.', 2),
('e4000000-0000-0000-0000-000000000040', 'C', 'Primary polydipsia', false, 'Ruled out because in primary polydipsia, urine osmolality typically rises appropriately during a water deprivation test as endogenous ADH responds normally, unlike the persistently low urine osmolality with failure to respond to desmopressin seen here.', 3),
('e4000000-0000-0000-0000-000000000040', 'D', 'Syndrome of inappropriate antidiuretic hormone secretion', false, 'Ruled out because SIADH causes hyponatraemia with concentrated urine, which is the opposite of the polyuria with dilute urine and mildly elevated sodium seen in this patient.', 4),
('e4000000-0000-0000-0000-000000000040', 'E', 'Osmotic diuresis due to poorly controlled diabetes mellitus', false, 'Ruled out because there is no mention of hyperglycaemia or glucosuria, and the specific history of long-term lithium use together with failure to respond to desmopressin points clearly to nephrogenic diabetes insipidus.', 5),
('e4000000-0000-0000-0000-000000000041', 'A', 'Intravenous co-amoxiclav as an inpatient', false, 'Ruled out because there is no evidence of systemic illness or pyelonephritis; an uncomplicated lower UTI does not require intravenous antibiotics or hospital admission.', 1),
('e4000000-0000-0000-0000-000000000041', 'B', 'No treatment is needed, as uncomplicated UTIs always resolve spontaneously', false, 'Ruled out because while some mild UTIs can occasionally improve without antibiotics, current guidance for symptomatic uncomplicated UTI in women is to treat promptly with a short course of antibiotics to relieve symptoms and reduce complications.', 2),
('e4000000-0000-0000-0000-000000000041', 'C', 'Oral nitrofurantoin or trimethoprim for three days, according to local guidance', true, 'Correct. This presentation is consistent with an uncomplicated lower urinary tract infection (cystitis) in a non-pregnant woman. First-line treatment is a short course (typically three days) of oral nitrofurantoin or trimethoprim, guided by local antimicrobial resistance patterns, without the need for further investigation in an otherwise well patient.', 3),
('e4000000-0000-0000-0000-000000000041', 'D', 'Urgent renal ultrasound before starting any antibiotics', false, 'Ruled out because imaging is not required for a straightforward, uncomplicated UTI in an otherwise well young woman; antibiotics can be started empirically based on symptoms and urinalysis.', 4),
('e4000000-0000-0000-0000-000000000041', 'E', 'A seven-day course of intravenous gentamicin', false, 'Ruled out because intravenous gentamicin is not appropriate or necessary for an uncomplicated lower urinary tract infection, which can be managed with a short oral antibiotic course.', 5),
('e4000000-0000-0000-0000-000000000042', 'A', 'Admission for intravenous antibiotics and fluid resuscitation, with blood and urine cultures taken first', true, 'Correct. This presentation, with fever, rigors, loin pain, tachycardia and relative hypotension alongside a positive urine dipstick, is consistent with acute pyelonephritis with features of sepsis. She requires admission for intravenous antibiotics (following local guidelines, e.g. co-amoxiclav or a cephalosporin depending on local policy), intravenous fluid resuscitation, and cultures taken before antibiotics to guide ongoing treatment, in line with the principles of sepsis management.', 1),
('e4000000-0000-0000-0000-000000000042', 'B', 'Discharge home with a three-day course of oral nitrofurantoin', false, 'Ruled out because this presentation shows features of sepsis (tachycardia, relative hypotension, fever with rigors) associated with pyelonephritis, which requires admission for intravenous treatment and monitoring, not outpatient management with a short-course antibiotic suitable only for uncomplicated cystitis.', 2),
('e4000000-0000-0000-0000-000000000042', 'C', 'Reassurance and simple analgesia only, with review in one week if not improved', false, 'Ruled out because this patient has signs of sepsis secondary to pyelonephritis and needs urgent treatment now, not a delayed review after a week without intervention.', 3),
('e4000000-0000-0000-0000-000000000042', 'D', 'Arrange an outpatient CT urogram before starting any antibiotics', false, 'Ruled out because antibiotics and fluid resuscitation should not be delayed for imaging in a septic patient; cultures should be taken and treatment started promptly, with imaging considered subsequently if there is concern about complications such as obstruction or abscess.', 4),
('e4000000-0000-0000-0000-000000000042', 'E', 'Start oral trimethoprim only, with no further monitoring required', false, 'Ruled out because the severity of this presentation, with signs of sepsis, requires admission for intravenous antibiotics and closer monitoring rather than oral treatment alone in the community.', 5),
('e4000000-0000-0000-0000-000000000043', 'A', 'Intravenous urogram as the first-line investigation', false, 'Ruled out because non-contrast CT KUB has largely replaced intravenous urography as the first-line investigation for suspected renal colic due to its superior sensitivity and avoidance of contrast-related risks.', 1),
('e4000000-0000-0000-0000-000000000043', 'B', 'Cystoscopy to directly visualise the bladder', false, 'Ruled out because cystoscopy is not the first-line investigation for suspected renal colic; it is more relevant to investigating bladder pathology such as suspected bladder tumours, and CT KUB is preferred initially here.', 2),
('e4000000-0000-0000-0000-000000000043', 'C', 'Urgent MRI of the lumbar spine', false, 'Ruled out because the clinical picture (loin-to-groin pain, haematuria, inability to lie still) is classic for renal colic rather than a spinal pathology, and CT KUB is the appropriate first-line investigation.', 3),
('e4000000-0000-0000-0000-000000000043', 'D', 'Reassurance and discharge without any imaging, as the diagnosis is clinical', false, 'Ruled out because while the clinical picture strongly suggests renal colic, imaging (CT KUB) is needed to confirm the diagnosis, size and location of any stone, and to exclude complications such as obstruction requiring urgent intervention.', 4),
('e4000000-0000-0000-0000-000000000043', 'E', 'Non-contrast CT of the kidneys, ureters and bladder (CT KUB)', true, 'Correct. This presentation, with sudden severe loin-to-groin pain, an inability to lie still, and microscopic haematuria without signs of infection, is classic for renal or ureteric colic due to a stone. Non-contrast CT KUB is the first-line imaging investigation to confirm the diagnosis, localise the stone, and assess for any complications such as obstruction.', 5),
('e4000000-0000-0000-0000-000000000044', 'A', 'Immediate percutaneous nephrostomy insertion bilaterally', false, 'Ruled out because the obstruction here is at the bladder outlet level (due to prostatic enlargement), which should first be addressed by urethral catheterisation; nephrostomy is generally reserved for upper tract (ureteric) obstruction that cannot be relieved by catheterisation or retrograde means.', 1),
('e4000000-0000-0000-0000-000000000044', 'B', 'High-dose intravenous furosemide to force diuresis past the obstruction', false, 'Ruled out because diuretics will not overcome a mechanical bladder outlet obstruction and may cause harm; the obstruction must be relieved first by catheterisation.', 2),
('e4000000-0000-0000-0000-000000000044', 'C', 'Start dialysis immediately without attempting to relieve the obstruction', false, 'Ruled out because the obstruction is readily reversible with catheterisation, which should be attempted first; renal function is likely to improve significantly once the obstruction is relieved, and dialysis is not the first step.', 3),
('e4000000-0000-0000-0000-000000000044', 'D', 'Urethral catheterisation to relieve the bladder outlet obstruction', true, 'Correct. The bilateral hydronephrosis and hydroureter with a significantly enlarged bladder residual volume in the context of prostatic enlargement indicate obstructive uropathy at the level of the bladder outlet. Urethral catheterisation is the first-line step to relieve the obstruction and allow renal function to recover; if catheterisation fails, suprapubic catheterisation would be the next step.', 4),
('e4000000-0000-0000-0000-000000000044', 'E', 'Discharge with oral antibiotics and outpatient urology follow-up', false, 'Ruled out because this is an acute obstructive AKI requiring immediate bladder decompression, not outpatient management, and there is no indication described here that infection is the primary problem.', 5),
('e4000000-0000-0000-0000-000000000045', 'A', 'Start empirical oral trimethoprim regardless of symptoms', false, 'Ruled out because treating asymptomatic bacteriuria in a catheterised patient with antibiotics does not improve outcomes and risks promoting antimicrobial resistance and side effects; antibiotics should be reserved for symptomatic infection.', 1),
('e4000000-0000-0000-0000-000000000045', 'B', 'No antibiotic treatment is needed, as she has asymptomatic bacteriuria', true, 'Correct. Bacteriuria is almost universal in patients with long-term indwelling catheters, and in the absence of systemic symptoms (fever, new confusion, loin pain, or other signs of infection), treating a positive dipstick or culture alone (asymptomatic bacteriuria) is not recommended, as it does not improve outcomes and contributes to antimicrobial resistance. Dipstick testing is also unreliable in catheterised patients and should generally be avoided for this reason.', 2),
('e4000000-0000-0000-0000-000000000045', 'C', 'Change the catheter and start intravenous antibiotics as an inpatient', false, 'Ruled out because there are no systemic symptoms indicating an active infection requiring treatment; changing the catheter may sometimes be considered as part of overall catheter care, but intravenous antibiotics are not indicated for asymptomatic bacteriuria.', 3),
('e4000000-0000-0000-0000-000000000045', 'D', 'Arrange urgent renal ultrasound to look for underlying obstruction', false, 'Ruled out because there is no clinical indication for urgent imaging in an asymptomatic patient with a positive urine dipstick alone; this reflects expected catheter-associated bacteriuria rather than a new acute problem.', 4),
('e4000000-0000-0000-0000-000000000045', 'E', 'Send urine for culture and treat based on sensitivities regardless of symptoms', false, 'Ruled out because treatment decisions in catheterised patients should be based on the presence of systemic or localising symptoms of infection, not on a positive culture alone; treating asymptomatic bacteriuria is not recommended.', 5),
('e4000000-0000-0000-0000-000000000046', 'A', 'Urgent (2-week wait) referral for investigation of suspected urological malignancy', true, 'Correct. Painless visible haematuria in an adult, particularly with a significant smoking history, is a red flag for urological malignancy (most commonly bladder cancer) and warrants urgent referral for further investigation, typically including cystoscopy and upper tract imaging, under a 2-week wait pathway.', 1),
('e4000000-0000-0000-0000-000000000046', 'B', 'Reassure the patient that this is likely a benign finding and advise no further action', false, 'Ruled out because painless visible haematuria in an older patient with a significant smoking history is a red flag symptom that must be urgently investigated to exclude urological malignancy, not dismissed as benign.', 2),
('e4000000-0000-0000-0000-000000000046', 'C', 'Treat empirically with a course of antibiotics for a presumed urinary tract infection', false, 'Ruled out because there is no evidence of infection on urinalysis (no leucocytes or nitrites mentioned, blood only), and painless haematuria in this risk group requires urgent investigation for malignancy rather than empirical antibiotic treatment.', 3),
('e4000000-0000-0000-0000-000000000046', 'D', 'Arrange routine outpatient urology review in three months', false, 'Ruled out because this presentation meets criteria for urgent (2-week wait) referral due to the red-flag nature of painless haematuria in a smoker of this age, rather than routine, non-urgent referral.', 4),
('e4000000-0000-0000-0000-000000000046', 'E', 'Repeat urinalysis in one month and refer only if haematuria persists', false, 'Ruled out because a single episode of painless visible haematuria in this risk group already warrants urgent referral; delaying to see if it recurs risks delayed diagnosis of a potentially serious underlying malignancy.', 5),
('e4000000-0000-0000-0000-000000000047', 'A', 'Simple renal cyst', false, 'Ruled out because simple renal cysts are typically non-enhancing, fluid-filled, and do not cause the systemic features (weight loss) or haematuria described here, which point instead to a malignant solid renal mass.', 1),
('e4000000-0000-0000-0000-000000000047', 'B', 'Renal cell carcinoma', true, 'Correct. A solid, enhancing renal mass found incidentally on imaging, especially with associated painless haematuria and unexplained weight loss, is highly suggestive of renal cell carcinoma, the most common primary renal malignancy in adults. Further staging investigations and urological referral are required.', 2),
('e4000000-0000-0000-0000-000000000047', 'C', 'Renal abscess', false, 'Ruled out because there is no history of fever, systemic sepsis, or preceding infection to suggest an abscess; the incidental finding of a solid enhancing mass with haematuria and weight loss is much more consistent with renal cell carcinoma.', 3),
('e4000000-0000-0000-0000-000000000047', 'D', 'Angiomyolipoma', false, 'Ruled out because angiomyolipomas are typically benign fat-containing lesions identifiable on CT by their characteristic low attenuation (fat density), and while they can bleed, the combination of haematuria and unexplained weight loss here is more suggestive of a malignant process.', 4),
('e4000000-0000-0000-0000-000000000047', 'E', 'Xanthogranulomatous pyelonephritis', false, 'Ruled out because this is a rare chronic inflammatory condition typically associated with obstructing staghorn calculi and recurrent infection, which are not described here; the clinical and imaging picture instead points to renal cell carcinoma.', 5),
('e4000000-0000-0000-0000-000000000048', 'A', 'Reassure the patient that a raised PSA is a normal finding with age and no further action is needed', false, 'Ruled out because although PSA can rise with age and benign prostatic hyperplasia, a PSA this significantly elevated combined with a hard, irregular prostate on examination are concerning findings that require urgent investigation for malignancy, not reassurance alone.', 1),
('e4000000-0000-0000-0000-000000000048', 'B', 'Start an alpha-blocker for presumed benign prostatic hyperplasia and review in six months', false, 'Ruled out because the examination findings (hard, irregular, asymmetric prostate) and markedly elevated PSA are red flags for malignancy rather than simple BPH, and require urgent referral rather than empirical BPH treatment and delayed review.', 2),
('e4000000-0000-0000-0000-000000000048', 'C', 'Repeat the PSA test in one year to assess the trend', false, 'Ruled out because these findings already meet criteria for urgent referral; waiting a year to repeat PSA would risk a significant delay in diagnosing and treating a potential prostate cancer.', 3),
('e4000000-0000-0000-0000-000000000048', 'D', 'Arrange a testicular ultrasound to investigate the urinary symptoms', false, 'Ruled out because the urinary symptoms and examination findings relate to the prostate, not the testes, and the appropriate next step is urgent urological referral, not testicular imaging.', 4),
('e4000000-0000-0000-0000-000000000048', 'E', 'Urgent (2-week wait) referral to urology for suspected prostate cancer', true, 'Correct. A hard, irregular, asymmetric prostate on digital rectal examination together with a significantly elevated PSA are red flag findings for prostate cancer and warrant urgent urology referral for further assessment, which would typically include MRI of the prostate and consideration of biopsy.', 5),
('e4000000-0000-0000-0000-000000000049', 'A', 'Reassure the patient that this is likely a benign cyst and review again in six months', false, 'Ruled out because a firm, irregular, non-transilluminating mass arising from the testis itself in a young man is a red flag for testicular cancer and requires urgent investigation, not simple reassurance and delayed review.', 1),
('e4000000-0000-0000-0000-000000000049', 'B', 'Start a course of antibiotics for presumed epididymo-orchitis', false, 'Ruled out because there is no history of pain, tenderness, fever, or urinary symptoms to suggest infection; a painless, firm, irregular testicular mass instead requires urgent evaluation for malignancy.', 2),
('e4000000-0000-0000-0000-000000000049', 'C', 'Arrange a testicular biopsy through the scrotum to obtain a tissue diagnosis', false, 'Ruled out because a trans-scrotal biopsy of a suspected testicular tumour is avoided due to the risk of seeding tumour cells into the scrotal skin and altering lymphatic drainage; diagnosis and management are guided by ultrasound and tumour markers, with orchidectomy (via an inguinal approach) providing the definitive tissue diagnosis and treatment.', 3),
('e4000000-0000-0000-0000-000000000049', 'D', 'Urgent scrotal ultrasound and referral to urology for suspected testicular cancer', true, 'Correct. A painless, firm, irregular testicular swelling arising from the body of the testis in a young man is a classic presentation of testicular cancer until proven otherwise. Urgent scrotal ultrasound is the key initial investigation, alongside prompt urological referral, as testicular cancer is one of the most curable solid organ cancers when diagnosed and treated early.', 4),
('e4000000-0000-0000-0000-000000000049', 'E', 'No further action is needed as testicular lumps in young men are usually harmless', false, 'Ruled out because testicular cancer is the most common solid malignancy in young men, and a firm, irregular, non-transilluminating testicular mass must be urgently investigated rather than dismissed.', 5),
('e4000000-0000-0000-0000-000000000050', 'A', 'Renal cell carcinoma', false, 'Ruled out because renal cell carcinoma typically presents as a solid parenchymal renal mass rather than a filling defect within the collecting system (renal pelvis), and does not typically show atypical urothelial cells on urine cytology in the way described here.', 1),
('e4000000-0000-0000-0000-000000000050', 'B', 'A simple non-obstructing renal stone', false, 'Ruled out because a stone would typically appear as a calcified filling defect on CT without contrast enhancement characteristics of a soft tissue mass, and would not explain positive urine cytology showing atypical urothelial cells.', 2),
('e4000000-0000-0000-0000-000000000050', 'C', 'Upper tract urothelial carcinoma', true, 'Correct. A filling defect in the renal pelvis on CT urogram with positive urine cytology for atypical urothelial cells, in a patient with painless haematuria and a normal cystoscopy (excluding a bladder source), is characteristic of upper tract urothelial carcinoma, which arises from the same urothelial lining as bladder cancer and shares risk factors such as smoking.', 3),
('e4000000-0000-0000-0000-000000000050', 'D', 'Bladder cancer with a normal cystoscopy result', false, 'Ruled out because cystoscopy has already excluded a bladder-based lesion; the filling defect is located in the upper tract (renal pelvis), pointing to upper tract urothelial carcinoma rather than bladder cancer.', 4),
('e4000000-0000-0000-0000-000000000050', 'E', 'Blood clot within the renal pelvis from unrelated causes', false, 'Ruled out because a blood clot would not typically persist as a discrete filling defect on follow-up imaging nor explain the presence of atypical urothelial cells on cytology; these findings together point to a genuine urothelial malignancy.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('e4000000-0000-0000-0000-000000000001', $x$Pre-renal AKI from volume depletion is worsened by ACE inhibitors/ARBs and NSAIDs, which impair the kidney's ability to autoregulate glomerular filtration pressure.$x$, 1),
('e4000000-0000-0000-0000-000000000001', 'Initial management of drug-associated pre-renal AKI is to stop the causative drugs and restore intravascular volume, not to escalate diuretics or renal replacement therapy prematurely.', 2),
('e4000000-0000-0000-0000-000000000001', 'A bland urinalysis (no blood/protein) supports a pre-renal rather than intrinsic renal cause of AKI.', 3),
('e4000000-0000-0000-0000-000000000002', 'Post-renal AKI from bladder outlet obstruction (e.g. BPH) is treated by relieving the obstruction first, typically with urethral or suprapubic catheterisation.', 1),
('e4000000-0000-0000-0000-000000000002', 'Bilateral hydronephrosis with a palpable bladder and a rising creatinine strongly suggests obstructive uropathy rather than an intrinsic renal process.', 2),
('e4000000-0000-0000-0000-000000000002', 'A large post-obstructive diuresis can follow catheterisation and should be monitored with fluid balance and electrolytes.', 3),
('e4000000-0000-0000-0000-000000000003', 'ECG changes of hyperkalaemia (tented T waves, widened QRS, loss of P waves, sine-wave pattern) indicate a medical emergency requiring immediate IV calcium gluconate to stabilise the myocardium.', 1),
('e4000000-0000-0000-0000-000000000003', 'Insulin-dextrose and nebulised salbutamol lower serum potassium by shifting it intracellularly but take longer to act and do not treat the acute arrhythmia risk.', 2),
('e4000000-0000-0000-0000-000000000003', 'Definitive potassium removal (resins, dialysis) is slower and should follow, not replace, emergency membrane-stabilising and potassium-shifting treatment.', 3),
('e4000000-0000-0000-0000-000000000004', 'Contrast-induced nephropathy risk is reduced by peri-procedural intravenous hydration, especially in patients with pre-existing renal impairment, diabetes, or dehydration.', 1),
('e4000000-0000-0000-0000-000000000004', 'Metformin should be temporarily withheld around iodinated contrast administration in patients with reduced eGFR due to the risk of lactic acidosis if contrast-induced AKI occurs.', 2),
('e4000000-0000-0000-0000-000000000004', 'CKD is a risk factor for, not an absolute contraindication to, contrast administration when the study is clinically necessary.', 3),
('e4000000-0000-0000-0000-000000000005', 'Absolute indications for urgent renal replacement therapy in AKI include refractory hyperkalaemia, severe fluid overload/pulmonary oedema, refractory metabolic acidosis, uraemic complications (encephalopathy, pericarditis) and certain toxin ingestions.', 1),
('e4000000-0000-0000-0000-000000000005', 'Medical management of hyperkalaemia (calcium gluconate, insulin-dextrose, salbutamol) should be escalated to dialysis if it fails to control potassium, especially alongside other RRT indications.', 2),
('e4000000-0000-0000-0000-000000000005', 'Rhabdomyolysis-induced AKI can progress rapidly to multi-organ complications requiring urgent renal replacement therapy.', 3),
('e4000000-0000-0000-0000-000000000006', 'Acute urinary retention is managed with immediate urethral (or suprapubic if urethral fails) catheterisation.', 1),
('e4000000-0000-0000-0000-000000000006', 'A smoothly enlarged, non-tender prostate on DRE is typical of benign prostatic hyperplasia, in contrast to the hard, irregular, nodular prostate associated with malignancy.', 2),
('e4000000-0000-0000-0000-000000000006', 'After decompression, an alpha-blocker is commonly started before a trial without catheter to improve the chance of successful voiding.', 3),
('e4000000-0000-0000-0000-000000000007', 'Testicular torsion should be treated as a surgical emergency based on clinical suspicion; imaging should not delay surgical exploration if the diagnosis is likely.', 1),
('e4000000-0000-0000-0000-000000000007', 'Absent cremasteric reflex and a high-riding, horizontally-lying testis are classic findings of torsion, in contrast to epididymo-orchitis which tends to have a more gradual onset.', 2),
('e4000000-0000-0000-0000-000000000007', 'Testicular salvage rates decline rapidly with time from onset, making time to surgery the most important prognostic factor.', 3),
('e4000000-0000-0000-0000-000000000008', $x$Epididymo-orchitis typically has a more gradual onset than torsion, with a preserved cremasteric reflex and pain relief on scrotal elevation (positive Prehn's sign).$x$, 1),
('e4000000-0000-0000-0000-000000000008', 'In sexually active young men, epididymo-orchitis is often due to Chlamydia trachomatis or Neisseria gonorrhoeae and requires empirical antibiotics plus sexual health screening and contact tracing.', 2),
('e4000000-0000-0000-0000-000000000008', 'Torsion must always be excluded first in acute scrotal pain, as it is time-critical, but the clinical picture here favours an infective cause.', 3),
('e4000000-0000-0000-0000-000000000009', 'A hydrocele is a painless, soft, transilluminating swelling surrounding the testis, caused by fluid accumulation within the tunica vaginalis.', 1),
('e4000000-0000-0000-0000-000000000009', 'Transillumination helps distinguish fluid-filled scrotal masses (hydrocele, epididymal cyst) from solid masses (tumour) which do not transilluminate.', 2),
('e4000000-0000-0000-0000-000000000009', 'Any scrotal mass arising from the testis itself that does not transilluminate should raise concern for testicular malignancy and prompt urgent ultrasound.', 3),
('e4000000-0000-0000-0000-000000000010', 'Paraphimosis occurs when a retracted foreskin cannot be returned over the glans, causing venous congestion and, if untreated, risk of ischaemic necrosis.', 1),
('e4000000-0000-0000-0000-000000000010', 'First-line management is prompt manual reduction with analgesia; if unsuccessful, a dorsal slit or emergency circumcision is required.', 2),
('e4000000-0000-0000-0000-000000000010', 'A common preventable cause is failure to reduce the foreskin back over the glans after catheterisation or examination in an uncircumcised patient.', 3),
('e4000000-0000-0000-0000-000000000011', 'ACE inhibitors/ARBs reduce proteinuria and slow CKD progression in patients with significant albuminuria (ACR greater than 30 mg/mmol), especially in diabetic nephropathy, independent of their blood pressure-lowering effect.', 1),
('e4000000-0000-0000-0000-000000000011', 'eGFR and potassium should be checked before and shortly after starting or up-titrating an ACE inhibitor/ARB in CKD.', 2),
('e4000000-0000-0000-0000-000000000011', 'CKD is diagnosed when reduced eGFR or evidence of kidney damage (e.g. proteinuria) persists for three months or more.', 3),
('e4000000-0000-0000-0000-000000000012', 'CKD-mineral bone disease results from reduced renal phosphate excretion and reduced activation of vitamin D, causing hyperphosphataemia, hypocalcaemia, and compensatory secondary hyperparathyroidism.', 1),
('e4000000-0000-0000-0000-000000000012', 'Management typically involves phosphate binders, active vitamin D analogues, and dietary phosphate restriction, aiming to control PTH and prevent renal osteodystrophy.', 2),
('e4000000-0000-0000-0000-000000000012', 'This biochemical pattern (low-normal calcium, raised phosphate, high PTH) differs from primary hyperparathyroidism, where calcium is typically raised and phosphate low.', 3),
('e4000000-0000-0000-0000-000000000013', 'Anaemia of CKD is typically normocytic and normochromic, resulting from reduced erythropoietin production as nephron mass declines.', 1),
('e4000000-0000-0000-0000-000000000013', 'Iron deficiency should be excluded and corrected before starting erythropoiesis-stimulating agents, as functional iron deficiency is common and reduces their effectiveness.', 2),
('e4000000-0000-0000-0000-000000000013', 'Other causes of anaemia (bleeding, B12/folate deficiency, marrow pathology) should be considered and excluded if the clinical picture is atypical.', 3),
('e4000000-0000-0000-0000-000000000014', 'Indications for nephrology referral in CKD include rapid eGFR decline, a sustained fall in eGFR category with a 25% or greater drop, ACR of 70 mg/mmol or more (unless known to be diabetic with modestly raised ACR already under care), or ACR greater than 30 mg/mmol with haematuria.', 1),
('e4000000-0000-0000-0000-000000000014', 'A rapid, unexplained deterioration in a previously stable CKD patient should prompt investigation for a superimposed pathology (e.g. glomerulonephritis, obstruction) rather than being assumed to be simple progression.', 2),
('e4000000-0000-0000-0000-000000000014', 'Good blood pressure control does not exclude the need for referral when other red-flag features of accelerated CKD progression are present.', 3),
('e4000000-0000-0000-0000-000000000015', 'CKD is an independent cardiovascular risk factor, and for many patients with earlier-stage CKD, cardiovascular events are a more likely outcome than progression to dialysis.', 1),
('e4000000-0000-0000-0000-000000000015', 'Management of CKD should include active cardiovascular risk reduction (blood pressure, lipids, smoking cessation, lifestyle) alongside renal-specific measures.', 2),
('e4000000-0000-0000-0000-000000000015', 'Progression to end-stage renal disease is variable and influenced by underlying cause, blood pressure control, proteinuria, and comorbidities, not an inevitable outcome of a CKD diagnosis.', 3),
('e4000000-0000-0000-0000-000000000016', 'NSAIDs reduce renal prostaglandin synthesis, impairing afferent arteriolar vasodilation and renal autoregulation, especially in the context of volume depletion.', 1),
('e4000000-0000-0000-0000-000000000016', $x$The 'triple whammy' combination of an NSAID, an ACE inhibitor/ARB, and a diuretic significantly increases the risk of AKI and should prompt caution or avoidance, particularly during acute illness.$x$, 2),
('e4000000-0000-0000-0000-000000000016', 'NSAIDs should generally be avoided or used with caution in older patients, those with CKD, or those who are volume-depleted or acutely unwell.', 3),
('e4000000-0000-0000-0000-000000000017', 'In bilateral (or unilateral in a single functioning kidney) renal artery stenosis, ACE inhibitors/ARBs can precipitate a significant rise in creatinine by removing angiotensin II-mediated efferent arteriolar constriction that maintains filtration pressure.', 1),
('e4000000-0000-0000-0000-000000000017', 'Renal function and potassium should be checked one to two weeks after starting or increasing the dose of an ACE inhibitor/ARB, particularly in at-risk patients.', 2),
('e4000000-0000-0000-0000-000000000017', 'A sharp creatinine rise shortly after starting an ACE inhibitor should prompt consideration of underlying renal artery stenosis.', 3),
('e4000000-0000-0000-0000-000000000018', 'Aminoglycosides (e.g. gentamicin) are directly nephrotoxic to proximal tubular cells, causing acute tubular necrosis, particularly with prolonged courses, higher trough levels, or pre-existing renal impairment.', 1),
('e4000000-0000-0000-0000-000000000018', $x$Granular ('muddy brown') casts on urine microscopy are characteristic of acute tubular necrosis.$x$, 2),
('e4000000-0000-0000-0000-000000000018', 'Aminoglycoside levels (peak and trough) and renal function should be monitored closely during treatment, especially beyond short courses, to reduce nephrotoxicity risk.', 3),
('e4000000-0000-0000-0000-000000000019', 'Drug-induced acute interstitial nephritis classically presents with fever, rash, eosinophilia, sterile pyuria and white cell casts, occurring days to weeks after starting the causative drug.', 1),
('e4000000-0000-0000-0000-000000000019', 'Common culprits include penicillins (including flucloxacillin), NSAIDs, and proton pump inhibitors.', 2),
('e4000000-0000-0000-0000-000000000019', 'The mainstay of treatment is prompt withdrawal of the causative drug; corticosteroids may be used in more severe or non-resolving cases.', 3),
('e4000000-0000-0000-0000-000000000020', 'Adequate periprocedural hydration with isotonic fluids is the main proven strategy for reducing contrast-induced nephropathy risk in patients with reduced renal function.', 1),
('e4000000-0000-0000-0000-000000000020', 'Using the minimum necessary contrast volume and avoiding other nephrotoxic agents around the time of the scan further reduces risk.', 2),
('e4000000-0000-0000-0000-000000000020', 'Risk factors for contrast-induced nephropathy include pre-existing CKD, diabetes, dehydration, heart failure, and concurrent nephrotoxic drug use.', 3),
('e4000000-0000-0000-0000-000000000021', 'Hyperkalaemia with ECG changes should be treated as a medical emergency regardless of symptoms, starting with IV calcium gluconate for cardiac membrane stabilisation.', 1),
('e4000000-0000-0000-0000-000000000021', 'Insulin-dextrose (and sometimes nebulised salbutamol) are used after calcium gluconate to shift potassium intracellularly and lower serum levels over the following hour.', 2),
('e4000000-0000-0000-0000-000000000021', 'The underlying cause of hyperkalaemia (e.g. CKD, drugs, tissue breakdown) should be identified and addressed alongside acute treatment.', 3),
('e4000000-0000-0000-0000-000000000022', 'SIADH causes euvolaemic hyponatraemia with inappropriately concentrated urine (high urine osmolality) relative to low plasma osmolality, and elevated urine sodium.', 1),
('e4000000-0000-0000-0000-000000000022', 'Small cell lung cancer is a classic cause of ectopic ADH secretion; other causes of SIADH include CNS pathology, pneumonia, and certain drugs (e.g. SSRIs, carbamazepine).', 2),
('e4000000-0000-0000-0000-000000000022', 'Thyroid and adrenal function should be checked to exclude other treatable causes of hyponatraemia before diagnosing SIADH.', 3),
('e4000000-0000-0000-0000-000000000023', 'Cranial diabetes insipidus results from reduced ADH secretion (often due to pituitary/hypothalamic injury, surgery or trauma), causing polyuria with dilute urine and rising plasma sodium/osmolality.', 1),
('e4000000-0000-0000-0000-000000000023', 'Nephrogenic diabetes insipidus results from renal resistance to ADH (e.g. lithium, hypercalcaemia) rather than reduced secretion, but produces a similar biochemical picture.', 2),
('e4000000-0000-0000-0000-000000000023', 'Desmopressin (a synthetic ADH analogue) improves cranial but not nephrogenic diabetes insipidus, and can help distinguish between the two.', 3),
('e4000000-0000-0000-0000-000000000024', 'Thiazide and loop diuretics are common causes of hypokalaemia through increased distal renal potassium excretion.', 1),
('e4000000-0000-0000-0000-000000000024', 'ECG features of hypokalaemia include flattened or inverted T waves, prominent U waves, ST depression, and (in severe cases) arrhythmias.', 2),
('e4000000-0000-0000-0000-000000000024', 'Other causes of hypokalaemia to consider include vomiting, diarrhoea, and endogenous or exogenous mineralocorticoid excess.', 3),
('e4000000-0000-0000-0000-000000000025', 'Severe hypercalcaemia of malignancy is managed with initial IV rehydration (0.9% sodium chloride) followed by an IV bisphosphonate to reduce bone resorption.', 1),
('e4000000-0000-0000-0000-000000000025', 'Thiazide diuretics worsen hypercalcaemia and should be avoided or stopped; loop diuretics have a limited role and should not precede adequate rehydration.', 2),
('e4000000-0000-0000-0000-000000000025', $x$Symptoms of hypercalcaemia include confusion, constipation, abdominal pain, polyuria and dehydration ('bones, stones, groans, moans, and thrones').$x$, 3),
('e4000000-0000-0000-0000-000000000026', 'Minimal change disease is the most common cause of nephrotic syndrome in children and typically presents with the triad of heavy proteinuria, hypoalbuminaemia and oedema.', 1),
('e4000000-0000-0000-0000-000000000026', 'It is usually highly responsive to corticosteroid treatment, and renal biopsy is often not required in typical paediatric presentations.', 2),
('e4000000-0000-0000-0000-000000000026', 'Nephrotic syndrome (heavy proteinuria, hypoalbuminaemia, oedema) should be distinguished from nephritic syndrome (haematuria, hypertension, mild-to-moderate proteinuria, red cell casts).', 3),
('e4000000-0000-0000-0000-000000000027', 'IgA nephropathy classically presents with recurrent episodes of macroscopic haematuria occurring at the same time as (or shortly after) an upper respiratory tract infection, in contrast to the delayed onset seen in post-streptococcal glomerulonephritis.', 1),
('e4000000-0000-0000-0000-000000000027', 'It is the most common primary glomerulonephritis and diagnosis is confirmed by renal biopsy showing IgA deposition in the mesangium, though this may not always be necessary if the clinical picture and course are typical.', 2),
('e4000000-0000-0000-0000-000000000027', 'Most cases have a benign course, but a minority progress to CKD, so blood pressure and renal function should be monitored over time.', 3),
('e4000000-0000-0000-0000-000000000028', 'Post-streptococcal glomerulonephritis typically occurs one to three weeks after a streptococcal throat or skin infection, presenting with haematuria, red cell casts, hypertension, oedema and variable renal impairment.', 1),
('e4000000-0000-0000-0000-000000000028', 'Most children recover renal function fully with supportive management (fluid and salt restriction, blood pressure control); the prognosis is generally more guarded in adults.', 2),
('e4000000-0000-0000-0000-000000000028', 'This is a nephritic syndrome pattern, distinguished from nephrotic syndrome by prominent haematuria and hypertension rather than predominant heavy proteinuria.', 3),
('e4000000-0000-0000-0000-000000000029', 'Anti-GBM disease (Goodpasture syndrome) causes rapidly progressive glomerulonephritis often combined with pulmonary haemorrhage, and is a medical emergency requiring urgent plasma exchange and immunosuppression.', 1),
('e4000000-0000-0000-0000-000000000029', 'Circulating anti-GBM antibodies target the alpha-3 chain of type IV collagen in the glomerular and alveolar basement membranes, explaining the combined renal-pulmonary presentation.', 2),
('e4000000-0000-0000-0000-000000000029', 'Prompt treatment is critical, as delay risks irreversible renal failure requiring long-term dialysis and life-threatening pulmonary haemorrhage.', 3),
('e4000000-0000-0000-0000-000000000030', $x$Membranous nephropathy is a common adult cause of nephrotic syndrome, with 'spike and dome' subepithelial deposits on electron microscopy.$x$, 1),
('e4000000-0000-0000-0000-000000000030', 'Primary membranous nephropathy is often associated with anti-PLA2R antibodies; secondary causes include malignancy, hepatitis B/C, and autoimmune disease (e.g. lupus), which warrant screening, especially in older patients.', 2),
('e4000000-0000-0000-0000-000000000030', 'Around a third of cases spontaneously remit, a third have a relapsing-remitting course, and a third progress to CKD, guiding decisions about immunosuppressive treatment.', 3),
('e4000000-0000-0000-0000-000000000031', 'Acute rejection should be suspected in a transplant recipient presenting with rising creatinine, graft tenderness, and sometimes fever or reduced urine output.', 1),
('e4000000-0000-0000-0000-000000000031', 'Diagnosis is usually confirmed by transplant biopsy, which distinguishes cellular from antibody-mediated rejection and guides specific treatment.', 2),
('e4000000-0000-0000-0000-000000000031', 'Other causes of graft dysfunction (calcineurin inhibitor toxicity, infection, recurrent disease, obstruction) should also be considered, but acute graft dysfunction always warrants urgent specialist assessment.', 3),
('e4000000-0000-0000-0000-000000000032', 'Tacrolimus is metabolised by cytochrome P450 3A4; drugs that inhibit this enzyme (e.g. macrolides such as clarithromycin, azole antifungals, grapefruit juice) can precipitate toxic tacrolimus levels.', 1),
('e4000000-0000-0000-0000-000000000032', 'Tacrolimus toxicity presents with neurotoxicity (tremor, headache, confusion) and nephrotoxicity (rising creatinine, hypertension), and requires urgent level monitoring and dose adjustment.', 2),
('e4000000-0000-0000-0000-000000000032', 'Any new medication in a transplant recipient should ideally be checked against their immunosuppressant regimen for interactions before prescribing.', 3),
('e4000000-0000-0000-0000-000000000033', 'Co-trimoxazole prophylaxis is given post-transplant specifically to prevent Pneumocystis jirovecii pneumonia, among other benefits.', 1),
('e4000000-0000-0000-0000-000000000033', 'PJP classically presents with fever, dry cough, progressive dyspnoea, and bilateral ground-glass changes on imaging in immunosuppressed patients.', 2),
('e4000000-0000-0000-0000-000000000033', 'Adherence to prophylactic medications is a key safety point to check in unwell transplant recipients presenting with infection.', 3),
('e4000000-0000-0000-0000-000000000034', 'New-onset diabetes after transplantation is a recognised long-term complication, particularly associated with tacrolimus and corticosteroid immunosuppression.', 1),
('e4000000-0000-0000-0000-000000000034', 'Risk factors include weight gain, older age, and pre-existing insulin resistance; monitoring of glucose and HbA1c is part of routine long-term transplant follow-up.', 2),
('e4000000-0000-0000-0000-000000000034', 'Management follows similar principles to type 2 diabetes, alongside review of immunosuppressive regimen where appropriate by the transplant team.', 3),
('e4000000-0000-0000-0000-000000000035', 'Chronic allograft dysfunction presents as a slow, progressive decline in graft function over months to years, often with mild proteinuria, and reflects a combination of chronic immune injury, calcineurin inhibitor nephrotoxicity, and other contributing factors.', 1),
('e4000000-0000-0000-0000-000000000035', 'It is a leading cause of long-term graft loss and should prompt specialist evaluation for reversible contributing causes even when drug levels are therapeutic.', 2),
('e4000000-0000-0000-0000-000000000035', 'This contrasts with acute rejection, which usually presents more rapidly and can be associated with graft tenderness or fever.', 3),
('e4000000-0000-0000-0000-000000000036', 'ADPKD typically presents in adulthood with hypertension, haematuria, flank pain, palpable bilateral renal masses, and a family history of kidney failure, often with an autosomal dominant inheritance pattern.', 1),
('e4000000-0000-0000-0000-000000000036', 'Screening relatives with renal ultrasound and offering screening for intracranial (berry) aneurysms in those with a family history of subarachnoid haemorrhage or symptoms are important aspects of ADPKD management.', 2),
('e4000000-0000-0000-0000-000000000036', 'Extra-renal manifestations include hepatic cysts, and less commonly cardiac valve abnormalities and intracranial aneurysms.', 3),
('e4000000-0000-0000-0000-000000000037', $x$Type 1 (distal) RTA causes a hyperchloraemic normal anion gap metabolic acidosis with an inappropriately alkaline urine pH, hypokalaemia, and a predisposition to nephrocalcinosis/kidney stones; it is associated with autoimmune conditions (e.g. Sjogren's syndrome) and certain drugs.$x$, 1),
('e4000000-0000-0000-0000-000000000037', 'Type 2 (proximal) RTA results from impaired proximal bicarbonate reabsorption and is associated with Fanconi syndrome.', 2),
('e4000000-0000-0000-0000-000000000037', 'Type 4 RTA is characterised by hyperkalaemia due to reduced aldosterone effect, distinguishing it from types 1 and 2.', 3),
('e4000000-0000-0000-0000-000000000038', 'Alport syndrome results from mutations in type IV collagen genes, most commonly X-linked, causing progressive glomerular disease, sensorineural hearing loss, and characteristic ocular findings (e.g. anterior lenticonus).', 1),
('e4000000-0000-0000-0000-000000000038', 'Family history is key: affected males in X-linked Alport syndrome are typically more severely affected than female carriers.', 2),
('e4000000-0000-0000-0000-000000000038', 'It should be considered in patients with persistent haematuria and a family history of renal failure, especially when combined with hearing or visual impairment.', 3),
('e4000000-0000-0000-0000-000000000039', 'Fanconi syndrome is a generalised proximal tubular dysfunction causing glucosuria (with normal blood glucose), aminoaciduria, phosphaturia, and proximal renal tubular acidosis.', 1),
('e4000000-0000-0000-0000-000000000039', 'Phosphate wasting in Fanconi syndrome leads to rickets in children or osteomalacia in adults.', 2),
('e4000000-0000-0000-0000-000000000039', 'Causes include inherited conditions (e.g. cystinosis, the most common cause in children) and acquired causes (drugs such as tenofovir or ifosfamide, heavy metals, or multiple myeloma in adults).', 3),
('e4000000-0000-0000-0000-000000000040', 'Lithium is a common cause of nephrogenic diabetes insipidus, causing renal resistance to ADH at the collecting duct.', 1),
('e4000000-0000-0000-0000-000000000040', 'A water deprivation test with subsequent desmopressin administration helps distinguish cranial DI (good response to desmopressin) from nephrogenic DI (poor or absent response).', 2),
('e4000000-0000-0000-0000-000000000040', 'Management of lithium-induced nephrogenic DI includes adequate fluid intake, reviewing the need for continued lithium therapy with psychiatry, and sometimes amiloride, which can reduce lithium-induced polyuria.', 3),
('e4000000-0000-0000-0000-000000000041', 'Uncomplicated lower UTIs in non-pregnant women are typically treated with a short (usually three-day) course of oral nitrofurantoin or trimethoprim, guided by local resistance patterns.', 1),
('e4000000-0000-0000-0000-000000000041', 'Features suggesting a complicated UTI or pyelonephritis (fever, loin pain, systemic illness, pregnancy, catheter, recurrent infection) should prompt a different approach, including possible admission or longer treatment course.', 2),
('e4000000-0000-0000-0000-000000000041', 'Routine imaging is not required for a first, uncomplicated UTI in an otherwise healthy young woman.', 3),
('e4000000-0000-0000-0000-000000000042', 'Acute pyelonephritis with signs of sepsis (tachycardia, hypotension, fever with rigors) requires admission for intravenous antibiotics and fluid resuscitation, following sepsis-management principles including cultures before antibiotics.', 1),
('e4000000-0000-0000-0000-000000000042', 'Renal angle tenderness with systemic symptoms differentiates pyelonephritis (upper urinary tract infection) from uncomplicated cystitis (lower urinary tract infection).', 2),
('e4000000-0000-0000-0000-000000000042', 'Imaging (e.g. renal ultrasound or CT) may be indicated if there is no improvement with treatment, to look for complications such as obstruction, abscess, or emphysematous pyelonephritis.', 3),
('e4000000-0000-0000-0000-000000000043', 'Renal/ureteric colic classically presents with sudden severe loin-to-groin pain, an inability to lie still (in contrast to the guarding seen with peritonitis), and microscopic or macroscopic haematuria.', 1),
('e4000000-0000-0000-0000-000000000043', 'Non-contrast CT KUB is the first-line imaging investigation for suspected renal colic due to high sensitivity for detecting stones.', 2),
('e4000000-0000-0000-0000-000000000043', 'NSAIDs (e.g. diclofenac, if not contraindicated) are typically the analgesic of choice for renal colic due to their effect on ureteric smooth muscle spasm, alongside antiemetics as needed.', 3),
('e4000000-0000-0000-0000-000000000044', 'Bladder outlet obstruction (e.g. from BPH) causing bilateral hydronephrosis and AKI is managed by prompt urethral (or suprapubic if urethral fails) catheterisation.', 1),
('e4000000-0000-0000-0000-000000000044', 'Upper urinary tract obstruction (e.g. from a ureteric stone or pelvic malignancy) not relievable by catheterisation may require nephrostomy or ureteric stenting instead.', 2),
('e4000000-0000-0000-0000-000000000044', 'Renal function typically improves after relief of obstruction, but a post-obstructive diuresis can occur and should be monitored with careful fluid balance.', 3),
('e4000000-0000-0000-0000-000000000045', 'Asymptomatic bacteriuria in a catheterised patient does not require antibiotic treatment, as bacterial colonisation of long-term catheters is expected and treatment does not reduce complications.', 1),
('e4000000-0000-0000-0000-000000000045', 'Urine dipstick testing is unreliable in catheterised patients (near-universal positive results) and should not be used to guide the decision to treat.', 2),
('e4000000-0000-0000-0000-000000000045', 'Antibiotics should be reserved for catheter-associated UTI presenting with systemic or localising symptoms such as fever, new confusion, rigors, or loin pain.', 3),
('e4000000-0000-0000-0000-000000000046', 'Painless visible haematuria in an adult, especially with risk factors such as smoking or occupational exposure to aromatic amines, is a red flag for urological malignancy and requires urgent (2-week wait) referral.', 1),
('e4000000-0000-0000-0000-000000000046', 'Bladder cancer is the most common cause of painless visible haematuria in this context, and cystoscopy is a key investigation.', 2),
('e4000000-0000-0000-0000-000000000046', 'A single episode of visible haematuria is sufficient to warrant urgent investigation; it should not be dismissed even if it does not recur.', 3),
('e4000000-0000-0000-0000-000000000047', 'Renal cell carcinoma classically presents with the triad of haematuria, flank pain and a palpable mass, though many cases are now detected incidentally on imaging performed for unrelated reasons.', 1),
('e4000000-0000-0000-0000-000000000047', 'Constitutional symptoms such as unexplained weight loss can occur with renal cell carcinoma and should raise suspicion of malignancy.', 2),
('e4000000-0000-0000-0000-000000000047', 'Staging CT (chest, abdomen, pelvis) and urological/oncological referral are required for further management once a suspicious solid renal mass is identified.', 3),
('e4000000-0000-0000-0000-000000000048', 'A hard, irregular, asymmetric prostate on DRE and a significantly elevated PSA are red flag features for prostate cancer requiring urgent (2-week wait) urology referral.', 1),
('e4000000-0000-0000-0000-000000000048', 'PSA is not cancer-specific and can be raised by BPH, prostatitis, urinary retention, and recent ejaculation or catheterisation, but marked elevation with abnormal examination findings should not be attributed to these alone.', 2),
('e4000000-0000-0000-0000-000000000048', 'Further assessment typically includes multiparametric MRI of the prostate, informing the decision about whether biopsy is needed.', 3),
('e4000000-0000-0000-0000-000000000049', 'A painless, firm, irregular mass arising from the testis itself (non-transilluminating) in a young man should be treated as suspicious for testicular cancer until proven otherwise, with urgent scrotal ultrasound.', 1),
('e4000000-0000-0000-0000-000000000049', 'Trans-scrotal biopsy is avoided in suspected testicular cancer due to the risk of tumour seeding; diagnosis and staging use ultrasound, tumour markers (AFP, beta-hCG, LDH), and radical inguinal orchidectomy.', 2),
('e4000000-0000-0000-0000-000000000049', 'Testicular cancer has a very high cure rate with prompt diagnosis and treatment, making urgent recognition and referral especially important.', 3),
('e4000000-0000-0000-0000-000000000050', 'Upper tract urothelial carcinoma should be considered when a patient with haematuria has a normal cystoscopy but an abnormal CT urogram (e.g. filling defect) and/or positive urine cytology.', 1),
('e4000000-0000-0000-0000-000000000050', 'Upper tract and bladder urothelial cancers share common risk factors (smoking, occupational carcinogen exposure) because they arise from the same urothelial lining throughout the urinary tract.', 2),
('e4000000-0000-0000-0000-000000000050', 'Full evaluation of haematuria in at-risk patients includes both lower tract assessment (cystoscopy) and upper tract imaging (CT urogram), as a lesion in either location can be missed if only one is performed.', 3);
